able CLI output.", records={{fields={}, line=447, name="DocsRenderModule"}}}, ["cosmic.doc.types"]={examples={}, file="lib/cosmic/doc/types.tl", functions={}, internal=true, module_doc=" Shared type definitions for the doc and docs modules.", records={{fields={}, line=3, name="doc_types"}}}, ["cosmic.embed"]={examples={{body="\n  local fs = require(\"cosmic.fs\")\n  local spawn = require(\"cosmic.child\")\n  local cosmic = arg[-1]\n\n  local tmpdir = fs.mkdtemp(\"/tmp/embed_example_XXXXXX\")\n\n  -- Create a simple app directory with a main.lua entry point\n  local appdir = fs.join(tmpdir, \"myapp\")\n  fs.makedirs(appdir)\n  fs.write(fs.join(appdir, \"main.lua\"), 'print(\"hello from myapp\")\\n')\n\n  -- Build it\n  local output = fs.join(tmpdir, \"hello\")\n  local r = spawn.run({cosmic, \"--embed\", appdir, \"--output\", output}) as spawn.Result\n  assert(r.ok, r.stderr)\n\n  -- Run it\n  r = spawn.run({output}) as spawn.Result\n  fs.rmrf(tmpdir)\n  print(r.stdout)\n  -- Output:\n  -- hello from myapp\n", description=" Example_embed_directory demonstrates embedding a directory into a new executable.\n The directory must contain a main.lua entry point.", expected_output="hello from myapp\n", line=10, name="Example_embed_directory"}, {body="\n  local fs = require(\"cosmic.fs\")\n  local spawn = require(\"cosmic.child\")\n  local cosmic = arg[-1]\n\n  local tmpdir = fs.mkdtemp(\"/tmp/embed_example_XXXXXX\")\n\n  -- Extract the running executable's zip contents\n  local extractdir = fs.join(tmpdir, \"extracted\")\n  local r = spawn.run({cosmic, \"--extract\", extractdir}) as spawn.Result\n  assert(r.ok, r.stderr)\n\n  -- The extracted directory contains main.lua and all bundled files\n  local main_exists = fs.isfile(fs.join(extractdir, \"main.lua\"))\n  fs.rmrf(tmpdir)\n  print(\"main.lua extracted:\", main_exists)\n  -- Output:\n  -- main.lua extracted:\ttrue\n", description=" Example_extract_roundtrip demonstrates extracting and re-embedding", expected_output="main.lua extracted:\ttrue\n", line=36, name="Example_extract_roundtrip"}, {body="\n  local fs = require(\"cosmic.fs\")\n  local spawn = require(\"cosmic.child\")\n  local cosmic = arg[-1]\n\n  local tmpdir = fs.mkdtemp(\"/tmp/embed_example_XXXXXX\")\n\n  -- Create an app that uses cosmic.child (a bundled library)\n  local appdir = fs.join(tmpdir, \"app\")\n  fs.makedirs(appdir)\n  fs.write(fs.join(appdir, \"main.lua\"), [[\nlocal child = require(\"cosmic.child\")\nlocal r = child.run({\"echo\", \"it works\"})\nio.write(r.stdout)\n]])\n\n  local output = fs.join(tmpdir, \"myapp\")\n  local r = spawn.run({cosmic, \"--embed\", appdir, \"--output\", output}) as spawn.Result\n  assert(r.ok, r.stderr)\n\n  r = spawn.run({output}) as spawn.Result\n  fs.rmrf(tmpdir)\n  print(r.stdout)\n  -- Output:\n  -- it works\n", description=" Example_embed_with_libraries demonstrates using cosmic libraries in embedded code", expected_output="it works\n", line=57, name="Example_embed_with_libraries"}, {body="\n  local fs = require(\"cosmic.fs\")\n  local spawn = require(\"cosmic.child\")\n  local cosmic = arg[-1]\n\n  local tmpdir = fs.mkdtemp(\"/tmp/embed_example_XXXXXX\")\n  local appdir = fs.join(tmpdir, \"myapp\")\n  fs.makedirs(appdir)\n\n  -- Write a Teal source file\n  local tl_file = fs.join(tmpdir, \"main.tl\")\n  fs.write(tl_file, 'local msg: string = \"hello from teal\"\\nprint(msg)\\n')\n\n  -- Compile .tl to .lua using cosmic --compile\n  local r = spawn.run({cosmic, \"--compile\", tl_file}) as spawn.Result\n  assert(r.ok, r.stderr)\n  local lua_source = r.stdout\n\n  -- Write the compiled Lua as the entry point\n  fs.write(fs.join(appdir, \"main.lua\"), lua_source)\n\n  -- Embed and run\n  local output = fs.join(tmpdir, \"from_teal\")\n  r = spawn.run({cosmic, \"--embed\", appdir, \"--output\", output}) as spawn.Result\n  assert(r.ok, r.stderr)\n\n  r = spawn.run({output}) as spawn.Result\n  fs.rmrf(tmpdir)\n  print(r.stdout)\n  -- Output:\n  -- hello from teal\n", description=" Example_embed_from_teal demonstrates the Teal workflow: compile .tl to .lua,\n then embed. The entry point must be main.lua since Teal is not compiled at\n runtime.", expected_output="hello from teal\n", line=87, name="Example_embed_from_teal"}}, file="lib/cosmic/embed.tl", functions={{description=" Recursively collect all files from a directory.\n Files are stored with paths relative to the directory root.", is_local=true, line=104, name="collect_dir", params={{description="The directory to collect from", name="dir", param_type="string"}}, returns={{description="Collected files, or nil on error", return_type="{FileToEmbed}"}, {description="Error message, or nil on success", return_type="string"}}, signature="(dir: string): {FileToEmbed} | nil, string"}, {is_local=true, line=107, name="do_walk", params={}, returns={}, signature="(base_dir: string, rel_prefix: string): string"}, {description=" Embed files and directories into a copy of the cosmic executable.\n Creates a new executable with the given paths appended to the zip archive.\n Paths can be files or directories. Directories are walked recursively and\n their contents are stored relative to the directory root. Files are stored\n with their given path (leading / stripped).", is_local=true, line=189, name="run", params={{description="List of file or directory paths to embed", name="paths", param_type="{string}"}, {description="Output path for the new executable (defaults to \"cosmic\")", name="output", param_type="string"}, {description="Path to the source executable (defaults to arg[-1])", name="exe_path", param_type="string"}}, returns={{description="Result with ok status, message, and file count", return_type="EmbedResult"}}, signature="(paths: {string}, output?: string, exe_path?: string): EmbedResult"}, {description=" Report whether a zip entry name would escape the extraction root\n (zip-slip). Rejects absolute paths — POSIX (`/x`), Windows/UNC\n (`\\x`, `\\\\server\\share`), and drive-letter (`C:\\x`, `C:/x`, `C:x`) —\n and any `..` traversal component. Both `/` and `\\` are treated as\n separators, since cosmic executables also extract on Windows where a\n `..\\evil` entry would otherwise slip past a POSIX-only guard.", is_local=true, line=317, name="unsafe_entry", params={{description="Archive entry name", name="name", param_type="string"}}, returns={{description="true if the entry is unsafe to extract", return_type="boolean"}}, signature="(name: string): boolean"}, {description=" Extract the zip contents of a cosmic executable to a directory.\n Creates the output directory if needed. Existing files are overwritten.", is_local=true, line=336, name="extract", params={{description="Directory to extract into", name="output_dir", param_type="string"}, {description="Path to the executable to extract (defaults to arg[-1])", name="exe_path", param_type="string"}}, returns={{description="Result with ok status, message, and file count", return_type="EmbedResult"}}, signature="(output_dir: string, exe_path?: string): EmbedResult"}}, module_doc=" Embed files and directories into a cosmic executable.\n\n cosmic is an executable zip — a native binary with a zip archive appended.\n Files in the archive are accessible at /zip/ paths from Lua code. The\n entry point is /zip/main.lua, configured by /zip/.args.\n\n Any file can be embedded (Lua source, data files, binaries, etc.), but\n the entry point must be a plain Lua file named main.lua. Teal files are\n not compiled at runtime, so compile them first:\n\n   cosmic --compile myapp.tl > myapp/main.lua\n\n Create a custom executable:\n\n   mkdir myapp\n   echo 'print(\"hello world\")' > myapp/main.lua\n   cosmic --embed myapp/ --output hello\n   ./hello\n\n Directory contents are stored relative to the directory root, so\n myapp/main.lua becomes /zip/main.lua in the resulting executable.\n Embedding a main.lua overrides the default entry point.\n\n The resulting executable keeps cosmic's bundled libraries, so embedded\n code can require(\"cosmic.fetch\"), require(\"lsqlite3\"), etc.\n\n Extract an executable's zip contents for inspection or modification:\n\n   cosmic --extract myapp/\n   # edit myapp/main.lua\n   cosmic --embed myapp/ --output myapp\n\n This roundtrips: extract produces exactly the files that embed consumes.", records={{description=" Result returned from embed and extract operations.", fields={{"ok", "boolean", ""}, {"message", "string", ""}, {"file_count", "integer", ""}}, line=42, name="EmbedResult"}, {description=" Options for adding files to a ZIP archive.", fields={{"mode", "number", ""}, {"method", "string", ""}}, line=49, name="AddOptions"}, {description=" Appender interface for modifying a ZIP archive in-place.", fields={{"add", "function(self: ZipAppender, name: string, content: string, options?: AddOptions): boolean, string", ""}, {"remove", "function(self: ZipAppender, name: string): boolean, string", ""}, {"close", "function(self: ZipAppender)", ""}}, line=55, name="ZipAppender"}, {description=" Stat record for zip file metadata.", fields={{"mode", "number", ""}, {"method", "number", ""}}, line=62, name="ZipStat"}, {description=" Reader interface for reading files from a ZIP archive.", fields={{"list", "function(self: ZipReader): {string}", ""}, {"read", "function(self: ZipReader, name: string): string | nil, string | nil", ""}, {"stat", "function(self: ZipReader, name: string): ZipStat | nil", ""}, {"close", "function(self: ZipReader)", ""}}, line=68, name="ZipReader"}, {description=" Directory handle whose `read` exposes the dirent d_type (unix.DT_DIR /\n DT_REG / DT_LNK / ... / DT_UNKNOWN) where the filesystem supports it,\n letting collect_dir skip a stat(2) call for entries d_type already\n identifies as neither a directory nor a regular file.", fields={{"read", "function(self): string, number", ""}, {"close", "function(self)", ""}}, line=79, name="EmbedDirHandle"}, {fields={{"name", "string", ""}, {"kind", "number", ""}}, line=86, name="DirEntry"}, {fields={{"path", "string", ""}, {"content", "string", ""}, {"stored_name", "string", ""}, {"mode", "number", ""}}, line=92, name="FileToEmbed"}, {fields={{"run", "function(paths: {string}, output?: string, exe_path?: string): EmbedResult", ""}, {"extract", "function(output_dir: string, exe_path?: string): EmbedResult", ""}, {"unsafe_entry", "function(name: string): boolean", ""}}, line=418, name="EmbedModule"}}}, ["cosmic.env"]={examples={{body="\n  local env = require(\"cosmic.env\")\n  local path = env.get(\"PATH\")\n  if path then\n    print(\"PATH is set\")\n  end\n  -- Output:\n  -- PATH is set\n", description=" Example_get demonstrates reading a single environment variable.\n This is the most common operation. env.get() returns the value\n as a string, or nil if the variable is not set.", expected_output="PATH is set\n", line=9, name="Example_get"}, {body="\n  local env = require(\"cosmic.env\")\n  local value = env.get(\"COSMIC_EXAMPLE_UNSET_VAR\")\n  print(tostring(value))\n  -- Output:\n  -- nil\n", description=" Example_get_missing demonstrates reading a variable that is not set.", expected_output="nil\n", line=20, name="Example_get_missing"}, {body="\n  local env = require(\"cosmic.env\")\n  local ok, err = env.set(\"COSMIC_EXAMPLE_VAR\", \"hello\")\n  if not ok then\n    print(\"set failed: \" .. tostring(err))\n    return\n  end\n  print(env.get(\"COSMIC_EXAMPLE_VAR\"))\n  env.unset(\"COSMIC_EXAMPLE_VAR\")\n  -- Output:\n  -- hello\n", description=" Example_set_and_get demonstrates setting and reading back a variable.", expected_output="hello\n", line=29, name="Example_set_and_get"}, {body="\n  local env = require(\"cosmic.env\")\n  env.set(\"COSMIC_EXAMPLE_TEMP\", \"temporary\")\n  env.unset(\"COSMIC_EXAMPLE_TEMP\")\n  print(tostring(env.get(\"COSMIC_EXAMPLE_TEMP\")))\n  -- Output:\n  -- nil\n", description=" Example_unset demonstrates removing an environment variable.", expected_output="nil\n", line=43, name="Example_unset"}, {body="\n  local env = require(\"cosmic.env\")\n  local vars = env.all()\n  local count = 0\n  for _ in pairs(vars) do\n    count = count + 1\n  end\n  print(\"environment has \" .. tostring(count > 0) .. \" variables\")\n  -- Output:\n  -- environment has true variables\n", description=" Example_all demonstrates listing all environment variables.\n env.all() returns a plain {string:string} table, unlike the\n raw unix.environ() call which has a less convenient format.", expected_output="environment has true variables\n", line=55, name="Example_all"}}, file="lib/cosmic/env.tl", functions={{description=" Get the value of an environment variable.\n Returns the default (nil if not given) when the variable is not set.", is_local=true, line=14, name="get", params={{description="The name of the environment variable", name="name", param_type="string"}, {description="Value to return when the variable is not set", name="default", param_type="string?"}}, returns={{description="The value of the environment variable, or the default", return_type="string?"}}, signature="(name: string, default?: string): string"}, {description=" Set an environment variable.", is_local=true, line=28, name="set", params={{description="The name of the environment variable", name="name", param_type="string"}, {description="The value to set", name="value", param_type="string"}, {description="If false, won't overwrite existing variables (defaults to true)", name="overwrite?", param_type="boolean"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message if setting failed", return_type="string?"}}, signature="(name: string, value: string, overwrite?: boolean): boolean, string"}, {description=" Unset an environment variable.", is_local=true, line=40, name="unset", params={{description="The name of the environment variable to remove", name="name", param_type="string"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message if unsetting failed", return_type="string?"}}, signature="(name: string): boolean, string"}, {description=" Clear all environment variables.\n Warning: This removes ALL environment variables from the process.", is_local=true, line=52, name="clear", params={}, returns={{description="True on success", return_type="boolean"}, {description="Error message if clearing failed", return_type="string?"}}, signature="(): boolean, string"}, {description=" Get all environment variables.\n Returns a table mapping variable names to their values.", is_local=true, line=63, name="all", params={}, returns={{description="A table of all environment variables", return_type="{string:string}"}}, signature="(): {string: string}"}, {description=" Get all environment variables as a list.\n Returns a list of \"KEY=VALUE\" strings suitable for passing to\n child.spawn or execve.", is_local=true, line=79, name="list", params={}, returns={{description="A list of \"KEY=VALUE\" strings", return_type="{string}"}}, signature="(): {string}"}}, module_doc=" Environment variable utilities.\n Provides get, set, unset, clear, and all functions for environment variables.\n For the common case of reading a single variable, use env.get() — it wraps\n os.getenv() internally and is the simplest approach. Use env.all() to get\n all variables as a {string:string} map parsed from unix.environ().", records={{fields={{"get", "function(name: string, default?: string): string", ""}, {"set", "function(name: string, value: string, overwrite?: boolean): boolean, string", ""}, {"unset", "function(name: string): boolean, string", ""}, {"clear", "function(): boolean, string", ""}, {"all", "function(): {string: string}", ""}, {"list", "function(): {string}", ""}}, line=88, name="EnvModule"}}}, ["cosmic.envd"]={examples={{body="\n  local envd = require(\"cosmic.envd\")\n  local env = require(\"cosmic.env\")\n  local fs = require(\"cosmic.fs\")\n\n  local tmpdir = os.getenv(\"TEST_TMPDIR\") or \"/tmp\"\n  local dir = fs.join(tmpdir, \"envd_example\")\n  fs.makedirs(dir)\n  fs.write(fs.join(dir, \"00-defaults\"), \"MY_APP_NAME=cosmic-example\\nMY_APP_PORT=8080\\n\")\n  fs.write(fs.join(dir, \"01-overrides\"), \"MY_APP_PORT=9090\\n\")\n\n  env.unset(\"MY_APP_NAME\")\n  env.unset(\"MY_APP_PORT\")\n\n  local result = envd.load_dir(dir)\n  print(\"loaded \" .. tostring(result.count) .. \" variable(s)\")\n  print(\"MY_APP_NAME=\" .. tostring(env.get(\"MY_APP_NAME\")))\n  print(\"MY_APP_PORT=\" .. tostring(env.get(\"MY_APP_PORT\")))\n\n  env.unset(\"MY_APP_NAME\")\n  env.unset(\"MY_APP_PORT\")\n  -- Output:\n  -- loaded 2 variable(s)\n  -- MY_APP_NAME=cosmic-example\n  -- MY_APP_PORT=9090\n", description=" Example_load_dir creates a temp directory with dotenv files and loads them.\n Files are concatenated in lexical order; later files override earlier ones.", expected_output="loaded 2 variable(s)\n  -- MY_APP_NAME=cosmic-example\n  -- MY_APP_PORT=9090\n", line=7, name="Example_load_dir"}, {body="\n  local fs = require(\"cosmic.fs\")\n  local spawn = require(\"cosmic.child\")\n  local cosmic = arg[-1]\n\n  local tmpdir = fs.mkdtemp(\"/tmp/envd_example_XXXXXX\")\n\n  -- 1. extract current executable\n  local extractdir = fs.join(tmpdir, \"extracted\")\n  local r = spawn.run({cosmic, \"--extract\", extractdir}) as spawn.Result\n  assert(r.ok, r.stderr)\n\n  -- 2. add env.d with a credential\n  local envd_dir = fs.join(extractdir, \"embed\", \"env.d\")\n  fs.makedirs(envd_dir)\n  fs.write(fs.join(envd_dir, \"credentials\"), \"MY_SECRET_TOKEN=tok-example-12345\\n\")\n\n  -- 3. re-embed with a main.lua that loads env.d and prints the var name\n  fs.write(fs.join(extractdir, \"main.lua\"), [[\nrequire(\"tl\").loader()\nlocal envd = require(\"cosmic.envd\")\nlocal env = require(\"cosmic.env\")\nlocal result = envd.load()\nprint(\"envd loaded \" .. result.count .. \" var(s)\")\nprint(\"MY_SECRET_TOKEN is \" .. (env.get(\"MY_SECRET_TOKEN\") and \"set\" or \"unset\"))\n]])\n\n  -- 4. build new executable\n  local output = fs.join(tmpdir, \"myapp\")\n  r = spawn.run({cosmic, \"--embed\", extractdir, \"--output\", output}) as spawn.Result\n  assert(r.ok, r.stderr)\n\n  -- 5. run it\n  r = spawn.run({output}) as spawn.Result\n  fs.rmrf(tmpdir)\n  print(r.stdout)\n  -- Output:\n  -- envd loaded 1 var(s)\n  -- MY_SECRET_TOKEN is set\n", description=" Example_extract_update_embed demonstrates the full cycle: extract the\n current executable's zip, add an env.d directory with credentials,\n re-embed, and run the new executable to show the vars are available.", expected_output="envd loaded 1 var(s)\n  -- MY_SECRET_TOKEN is set\n", line=37, name="Example_extract_update_embed"}, {body="\n  local envd = require(\"cosmic.envd\")\n\n  -- basic expansion: later values can reference earlier ones\n  local vars = envd.parse(\"HOST=localhost\\nPORT=8080\\nURL=http://${HOST}:${PORT}\\n\")\n  print(\"URL=\" .. vars[\"URL\"])\n\n  -- ${VAR:-default} uses fallback when unset or empty\n  vars = envd.parse(\"TIMEOUT=${MISSING:-30}\\n\")\n  print(\"TIMEOUT=\" .. vars[\"TIMEOUT\"])\n\n  -- ${VAR-default} uses fallback only when unset (empty is kept)\n  vars = envd.parse(\"EMPTY=\\nKEEP=${EMPTY-fallback}\\n\")\n  print(\"KEEP=\" .. vars[\"KEEP\"])\n  -- Output:\n  -- URL=http://localhost:8080\n  -- TIMEOUT=30\n  -- KEEP=\n", description=" Example_variable_expansion shows ${VAR} expansion in dotenv values.\n Variables defined earlier in the same file or from an external context\n are available for expansion. Supports ${VAR:-default} and ${VAR-default}.", expected_output="URL=http://localhost:8080\n  -- TIMEOUT=30\n  -- KEEP=\n", line=81, name="Example_variable_expansion"}}, file="lib/cosmic/envd.tl", functions={{description=" Expand ${VAR}, ${VAR:-default}, and ${VAR-default} references in a\n string. Looks up variables in ctx first, then falls back to the\n process environment. Undefined variables with no default expand to\n empty string.", is_local=true, line=54, name="expand", params={{description="The string to expand", name="value", param_type="string"}, {description="string} Context of previously defined variables", name="ctx", param_type="{string:"}}, returns={{description="The expanded string", return_type="string"}}, signature="(value: string, ctx: {string: string}): string"}, {description=" Parse a single dotenv-format string. Returns a map of KEY=VALUE pairs.\n Lines starting with # are comments. Blank lines are skipped.\n Keys must match [A-Za-z_][A-Za-z0-9_]*.\n Values undergo ${VAR} expansion using ctx as the lookup context.", is_local=true, line=91, name="parse", params={{description="The dotenv content to parse", name="content", param_type="string"}, {description="string} Context for variable expansion (default: {})", name="ctx?", param_type="{string:"}}, returns={{description="string} Parsed key-value pairs", return_type="{string:"}}, signature="(content: string, ctx?: {string: string}): {string: string}"}, {description=" Load env vars from a directory of dotenv files. Files are read in\n lexical order and concatenated — later files can override keys from\n earlier files. Existing env vars are never overwritten.\n When COSMIC_DEBUG is set, prints the name (not value) of each variable\n set or skipped to stderr, along with the source file.", is_local=true, line=122, name="load_dir", params={{description="The directory to read dotenv files from", name="dir", param_type="string"}}, returns={{description="Result with count of variables set and source path", return_type="LoadResult"}}, signature="(dir: string): LoadResult"}, {description=" Load env vars from the embedded /zip/embed/env.d directory.\n Call this early in startup, before code that depends on the variables.", is_local=true, line=203, name="load", params={}, returns={{description="Result with count of variables set and source path", return_type="LoadResult"}}, signature="(): LoadResult"}}, module_doc=" Load environment variables from an embedded env.d directory.\n\n Files in the env.d directory use dotenv format: each line is either\n a KEY=VALUE assignment or a comment (lines starting with #). Files\n are read in lexical (sorted) order and concatenated — later assignments\n to the same key within env.d win. Existing environment variables are\n NOT overwritten; the real environment always takes precedence.\n\n This follows the dotenv convention for embedding credentials (API keys,\n tokens) into a cosmic executable:\n\n   mkdir env.d\n   echo 'ANTHROPIC_API_KEY=sk-ant-...' > env.d/api\n   cosmic --embed env.d\n\n At startup, call envd.load() to read /zip/embed/env.d/ and set any\n variables not already present in the environment.\n\n Key names must match [A-Za-z_][A-Za-z0-9_]*. Blank lines and lines\n starting with # are ignored. Values are taken as-is after the first =\n (no trimming, no quote stripping).\n\n Variable expansion is supported in values using ${VAR} syntax:\n   ${VAR}            expands to the value of VAR\n   ${VAR:-default}   expands to default if VAR is unset or empty\n   ${VAR-default}    expands to default if VAR is unset\n Variables defined earlier in the same file or in earlier files (lexical\n order) are available for expansion, as are existing environment variables.\n Undefined variables with no default expand to empty string.\n\n Set COSMIC_DEBUG=1 to see which vars are loaded and which are skipped.", records={{description=" Result returned from load operations.", fields={{"count", "integer", ""}, {"source", "string", ""}, {"errors", "{string}", " Per-entry failures (unreadable files, env.set errors). Loading\n continues past them; an empty list means a clean load."}}, line=39, name="LoadResult"}, {fields={{"load", "function(): LoadResult", ""}, {"load_dir", "function(dir: string): LoadResult", ""}, {"parse", "function(content: string, ctx?: {string: string}): {string: string}", ""}, {"expand", "function(value: string, ctx: {string: string}): string", ""}}, line=207, name="EnvdModule"}}}, ["cosmic.errno"]={examples={}, file="lib/cosmic/errno.tl", functions={{description=" Format an error as one canonical string, optionally prefixed with the\n failing operation or context. Binding error strings already name the\n failing call (`\"mkdir: EACCES: Permission denied\"`); when a prefix is\n supplied, that lowercase `call: ` head is dropped so the operation is\n not stated twice (`\"mkdir: /x: EACCES: Permission denied\"`, not\n `\"mkdir: /x: mkdir: EACCES: ...\"`). Errno names are uppercase, so\n they are never mistaken for a call head. Any non-string value falls\n back to `tostring`; `nil` becomes `\"unknown error\"`.", is_local=true, line=27, name="str", params={{description="the error value (a string, or nil)", name="err", param_type="any"}, {description="operation/context to prepend", name="prefix?", param_type="string"}}, returns={{description="canonical error string", return_type="string"}}, signature="(err: any, prefix?: string): string"}, {description=" The numeric errno for a named constant (e.g. `code(\"ENOENT\")`), or nil\n if the host does not define it. A thin lookup over `unix.E*`.", is_local=true, line=49, name="code", params={{description="errno constant name", name="name", param_type="string"}}, returns={{description="errno number", return_type="integer?"}}, signature="(name: string): integer"}, {description=" True when a failed call's numeric errno (the third return value of a\n failed `unix.*` call) matches the named constant. Enables programmatic\n handling without string-matching:\n     local n, err, eno = unix.poll(fds, timeout)\n     if errno.is(eno, \"EINTR\") then retry() end", is_local=true, line=63, name="is", params={{description="the numeric errno from a failed call", name="eno", param_type="any"}, {description="errno constant name (e.g. \"ENOENT\")", name="name", param_type="string"}}, returns={{return_type="boolean"}}, signature="(eno: any, name: string): boolean"}, {description=" The errno constant name embedded in a canonical error string, or nil\n if the message carries none. Enables programmatic checks on errors\n whose numeric errno is no longer at hand:\n     local data, err = fs.read(path)\n     if errno.name_of(err) == \"ENOENT\" then ... end\n Matches the first `ENAME:` token — an uppercase word starting with E\n at a word boundary, so uppercase tails of other words (`\"FAILED:\"`)\n are never mistaken for an errno name.", is_local=true, line=83, name="name_of", params={{description="the error string", name="msg", param_type="string"}}, returns={{description="errno constant name (e.g. \"ENOENT\"), or nil", return_type="string?"}}, signature="(msg: string): string"}}, module_doc=" Error information from system calls.\n\n Failed `cosmo.unix` calls return `nil, err, errno`: a formatted string\n (`\"open: ENOENT: No such file or directory\"`) plus the numeric errno.\n This module provides the canonical formatter (`str`) that most\n `cosmic.*` wrappers use to add operation context, and helpers for\n programmatic errno handling (`is`, `code`), so error messages share\n one shape across the stdlib:\n\n     local ok, err = unix.mkdir(path, mode)\n     if not ok then return false, errno.str(err, \"mkdir: \" .. path) end\n     -- -> \"mkdir: /x: EACCES: Permission denied\"", records={}}, ["cosmic.example"]={examples={}, file="lib/cosmic/example.tl", functions={{description=" Parse a .tl file and extract Example_* functions with their expected output.\n Finds all local functions named Example_* and extracts their code and -- Output: comments.", is_local=true, line=34, name="parse_examples", params={{description="The source code to parse", name="source", param_type="string"}}, returns={{description="List of parsed examples", return_type="{Example}"}}, signature="(source: string): {Example}"}, {is_local=true, line=43, name="count_lines", params={}, returns={}, signature="(s: string, start_pos: integer, end_pos: integer): integer"}, {description=" Run a single example and capture its output.\n Executes the example code and compares actual output with