\")\n  local proc = require(\"cosmic.proc\")\n\n  local srv, port = net.listen_tcp(\"127.0.0.1\", 0)\n  local s = srv as net.Socket\n  local pid = proc.fork()\n  if pid == 0 then\n    local conn = s:accept() as net.Socket\n    conn:recv(4096)\n    conn:send(\"HTTP/1.1 200 OK\\r\\nContent-Length: 5\\r\\nConnection: close\\r\\n\\r\\nhello\")\n    conn:close()\n    os.exit(0)\n  end\n  s:close()\n\n  local result = fetch.fetch(\"http://127.0.0.1:\" .. math.tointeger(port) .. \"/\",\n    {allow_private = true})\n  proc.wait(pid)\n  print(result.status, result.body, result:is_success())\n  -- Output:\n  -- 200\thello\ttrue\n", description=" Example_get demonstrates a simple HTTP GET request against a local\n server: fork a child to answer one request, then fetch from it.", expected_output="200\thello\ttrue\n", line=9, name="Example_get"}, {body="\n  local fetch = require(\"cosmic.fetch\")\n  local net = require(\"cosmic.net\")\n  local proc = require(\"cosmic.proc\")\n\n  local srv, port = net.listen_tcp(\"127.0.0.1\", 0)\n  local s = srv as net.Socket\n  local pid = proc.fork()\n  if pid == 0 then\n    local responses = {\n      \"HTTP/1.1 503 Service Unavailable\\r\\nContent-Length: 0\\r\\nConnection: close\\r\\n\\r\\n\",\n      \"HTTP/1.1 200 OK\\r\\nContent-Length: 2\\r\\nConnection: close\\r\\n\\r\\nok\",\n    }\n    for _, resp in ipairs(responses) do\n      local conn = s:accept() as net.Socket\n      conn:recv(4096)\n      conn:send(resp)\n      conn:close()\n    end\n    os.exit(0)\n  end\n  s:close()\n\n  local result = fetch.fetch(\"http://127.0.0.1:\" .. math.tointeger(port) .. \"/\", {\n      allow_private = true,\n      max_attempts = 2,\n      base_delay = 0.01, -- keep the example fast; default is 0.5s\n    })\n  proc.wait(pid)\n  print(result.status, result.body)\n  -- Output:\n  -- 200\tok\n", description=" Example_retry demonstrates the default retry policy: transport errors\n (dns/connect/timeout) and 429/502/503/504 responses are retried for\n idempotent methods, with full-jitter exponential backoff. Here the\n server answers 503 once, then 200; max_attempts = 2 rides it out.", expected_output="200\tok\n", line=38, name="Example_retry"}, {body="\n  local fetch = require(\"cosmic.fetch\")\n  local net = require(\"cosmic.net\")\n  local proc = require(\"cosmic.proc\")\n\n  local srv, port = net.listen_tcp(\"127.0.0.1\", 0)\n  local s = srv as net.Socket\n  local pid = proc.fork()\n  if pid == 0 then\n    local body = \"alpha\\nbeta\\ngamma\\n\"\n    local conn = s:accept() as net.Socket\n    conn:recv(4096)\n    conn:send(\"HTTP/1.1 200 OK\\r\\nContent-Length: \" .. #body\n      .. \"\\r\\nConnection: close\\r\\n\\r\\n\" .. body)\n    conn:close()\n    os.exit(0)\n  end\n  s:close()\n\n  local result = fetch.stream(\"http://127.0.0.1:\" .. math.tointeger(port) .. \"/\",\n    {allow_private = true})\n  for line in result.reader:lines() do\n    print(line)\n  end\n  result.reader:close()\n  proc.wait(pid)\n  -- Output:\n  -- alpha\n  -- beta\n  -- gamma\n", description=" Example_stream_lines demonstrates streaming a response and iterating\n its lines incrementally instead of buffering the whole body.", expected_output="alpha\n  -- beta\n  -- gamma\n", line=74, name="Example_stream_lines"}}, file="lib/cosmic/fetch/init.tl", functions={{is_local=true, line=114, name="validate_url", params={}, returns={}, signature="(url: string): string"}, {is_local=true, line=131, name="has_forbidden_byte", params={}, returns={}, signature="(s: string): boolean"}, {description=" Reject header names or values that carry a CR, LF, or NUL. HTTP headers\n are CRLF-delimited, so an embedded CR/LF in a name or value smuggles\n additional header lines (or a body) past cosmo.Fetch — a request-splitting\n / header-injection vector (audit §2.3). The error names the offending\n header but never echoes the raw control bytes back.", is_local=true, line=142, name="validate_headers", params={{description="string} request headers, or nil", name="he