file="lib/cosmic/fetch/headers.tl", functions={{description=" Normalize a raw header table from cosmo.Fetch/FetchStream.", is_local=true, line=13, name="normalize", params={{description="any} headers as returned by the C binding, or nil", name="raw", param_type="{string:"}}, returns={{description="string} lowercase names; repeats joined with \", \"", return_type="{string:"}, {description="{string}} lowercase names; all values in order", return_type="{string:"}}, signature="(raw: {string: any}): {string: string}, {string: {string}}"}}, internal=true, module_doc=" Response-header normalization for the cosmic.fetch module.\n cosmo.Fetch/FetchStream return headers with original-case names, and\n repeatable headers (Vary, Cache-Control, ...) arrive as nested array\n tables even though the binding declares {string: string}. This chunk\n flattens that into two honest views in one pass:\n - headers: lowercase names, repeated values joined \", \" (RFC 9110 §5.3)\n - raw_headers: lowercase names, every value in arrival order", records={{fields={{"normalize", "function(raw: {string: any}): {string: string}, {string: {string}}", ""}}, line=39, name="FetchHeadersModule"}}}, ["cosmic.format"]={examples={}, file="lib/cosmic/format/init.tl", functions={{description=" Count newlines in a string using plain find (faster than gmatch for counting).", is_local=true, line=41, name="count_newlines", params={}, returns={}, signature="(s: string): integer"}, {description=" Return true if item is a long bracket string (e.g. [[...]] or [=[...]=]).", is_local=true, line=54, name="is_long_string", params={}, returns={}, signature="(item: Item): boolean"}, {description=" Determine the language mode from a filename.", is_local=true, line=59, name="detect_lang", params={}, returns={}, signature="(filename: string): string"}, {description=" Build a flat, position-sorted list of items from the token stream.\n Extracts comments from tokens and interleaves them by position.", is_local=true, line=68, n