 subdir\n  -- cleaned up\n", line=4, name="Example_basic"}, {body="\n  local fs = require(\"cosmic.fs\")\n  print(fs.normalize(\"/usr/./lib\"))\n  print(fs.normalize(\"/usr/lib/../bin\"))\n  print(fs.normalize(\"a/b/../c\"))\n  print(fs.normalize(\"//usr///lib//\"))\n  -- Output:\n  -- /usr/lib\n  -- /usr/bin\n  -- a/c\n  -- /usr/lib\n", description=" Example_normalize demonstrates path normalization", expected_output="/usr/lib\n  -- /usr/bin\n  -- a/c\n  -- /usr/lib\n", line=53, name="Example_normalize"}, {body="\n  local fs = require(\"cosmic.fs\")\n  local root: string\n  local extension: string\n  root, extension = fs.splitext(\"archive.tar.gz\")\n  print(root, extension)\n  root, extension = fs.splitext(\".bashrc\")\n  if extension == \"\" then\n    print(root)\n  else\n    print(root, extension)\n  end\n  root, extension = fs.splitext(\"/path/to/file.txt\")\n  print(root, extension)\n  -- Output:\n  -- archive.tar\t.gz\n  -- .bashrc\n  -- /path/to/file\t.txt\n", description=" Example_splitext demonstrates extension splitting", expected_output="archive.tar\t.gz\n  -- .bashrc\n  -- /path/to/file\t.txt\n", line=67, name="Example_splitext"}, {body="\n  local fs = require(\"cosmic.fs\")\n  print(fs.relpath(\"/usr/lib\", \"/usr\"))\n  print(fs.relpath(\"/usr/lib\", \"/usr/bin\"))\n  print(fs.relpath(\"/foo\", \"/bar\"))\n  -- Output:\n  -- lib\n  -- ../lib\n  -- ../foo\n", description=" Example_relpath demonstrates computing relative paths", expected_output="lib\n  -- ../lib\n  -- ../foo\n", line=88, name="Example_relpath"}}, file="lib/cosmic/fs/init.tl", functions={{is_local=true, line=29, name="make_dir", params={}, returns={}, signature="(raw: RawDir): Dir"}, {description=" Get file metadata.\n Follows symbolic links: stat on a symlink describes its target.\n Use lstat() to inspect the symlink itself.", is_local=true, line=76, name="stat", params={{description="Path to the file or directory", name="path", param_type="string"}}, returns={{description="| nil File m