r, \"mkdtemp failed\")\n\n  local subdir = fs.join(tmpdir, \"src\")\n  assert(fs.makedirs(subdir))\n  assert(fs.write(fs.join(subdir, \"main.lua\"), \"-- main\\n\"))\n  assert(fs.write(fs.join(subdir, \"util.lua\"), \"-- util\\n\"))\n  assert(fs.write(fs.join(tmpdir, \"README.txt\"), \"readme\\n\"))\n\n  -- collect returns full paths (or nil if the root could not be opened);\n  -- sort for deterministic output.\n  local luafiles = (fs.collect(tmpdir, \"*.lua\") or {}) as {string}\n  table.sort(luafiles)\n  for _, p in ipairs(luafiles) do\n    -- print only the basename so output is not path-dependent.\n    print(fs.basename(p))\n  end\n\n  fs.rmrf(tmpdir)\n  -- Output:\n  -- main.lua\n  -- util.lua\n", description=" Example_collect demonstrates collecting files matching a glob pattern.", expected_output="main.lua\n  -- util.lua\n", line=42, name="Example_collect"}, {body="\n  local fs = require(\"cosmic.fs\")\n\n  local tmpdir = fs.mkdtemp(\"/tmp/files_ex_XXXXXX\")\n  assert(tmpdir, \"mkdtemp failed\")\n\n  assert(fs.write(fs.join(tmpdir, \"a.txt\"), \"a\\n\"))\n  assert(fs.write(fs.join(tmpdir, \"b.txt\"), \"b\\n\"))\n\n  local names: {string} = {}\n  -- files() returns nil, err if the root cannot be opened; assert passes\n  -- the iterator and its closing guard through on success (the cast only\n  -- narrows the type — it does not drop the extra return values).\n  for p in assert(fs.files(tmpdir, \"*.txt\")) as fs.FileIter do\n    table.insert(names, fs.basename(p))\n  end\n  table.sort(names)\n  for _, n in ipairs(names) do\n    print(n)\n  end\n\n  fs.rmrf(tmpdir)\n  -- Output:\n  -- a.txt\n  -- b.txt\n", description=" Example_files demonstrates the files() iterator for streaming traversal.", expected_output="a.txt\n  -- b.txt\n", line=70, name="Example_files"}}, file="lib/cosmic/fs/walk.tl", functions={{description=" Shared per-directory loop. Consumes (and closes) an already-open\n handle, records the first subtree error in errbox[1], and returns\n true when a visitor asked to stop the walk.", is_local=true, line=34, name="walk_entries", params={}, returns={}, signature="(dir: string, h: WalkDirHandle,\n    visitor: function(string, string, WalkStat, T): (WalkAction ...), ctx: T,\n    errbox: {string}): boolean"}, {description=" Walk a directory tree, calling visitor for each entry.\n Recursively traverses all subdirectories.\n Does NOT recurse into symlinked directories to prevent symlink cycles.\n The visitor receives four arguments:\n   path  (string)  — the full path to the entry (e.g. \"dir/sub/file.txt\").\n   name  (string)  — the basename of the entry (e.g. \"file.txt\").\n   st    (WalkStat) — stat result for the entry.\n   ctx   (T)       — the context value passed to walk().\n The visitor's return value controls the traversal:\n   nil    — continue (a visitor that returns nothing keeps today's behavior)\n   \"skip\" — do not descend into this entry (dirs only; no-op for files)\n   \"stop\" — end the walk now; walk returns ctx plus any first error\n IMPORTANT: do NOT join path and name — path is already the full path.\n Joining them produces doubled paths like \"dir/sub/file.txt/file.txt\".\n WalkStat is defined in cosmic.fs.types. Import it as:\n   local types = require(\"cosmic.fs.types\")\n   local type WalkStat = types.WalkStat\n If the root directory cannot be opened, returns nil plus the error.\n Failures below the root (unreadable subdirectory, vanished entry) do\n not stop the walk; the first such error is returned alongside the\n context so callers never mistake a partial walk for a complete one.", is_local=true, line=112, name="walk", params={{description="The directory to walk", name="dir", param_type="string"}, {description="Called for each entry: function(path, name, st, ctx): nil|\"skip\"|\"stop\"", name="visitor", param_type="function"}, {description="Optional context passed to every visitor call", name="ctx", param_type="T"}}, returns={{description="| nil The context object, or nil if the root could not be opened", return_type="T"}, {description="First error encountered, if any", return_type="string"}}, signature="(dir: string, visitor: function(string, string, WalkStat, T): (WalkAction ...), ctx?: T): T | nil, string"}, {description=" Convert a glob pattern to a Lua pattern.\n Supports * (any chars), ? (single char), and character classes [abc].", is_local=true, line=127, name="glob_to_pattern", params={{description="The glob pattern", name="glob", param_type="string"}}, returns={{description="The equivalent Lua pattern", return_type="string"}}, signature="(glob: string): string"}, {description=" Collect file paths matching a pattern.\n Recursively walks directory tree and returns matching file paths.\n If the root directory cannot be opened, returns nil plus the error.\n Failures below the root do not stop the collection; the first such\n error is returned alongside the results.", is_local=true, line=147, name="collect", params={{description="The directory to search", name="dir", param_type="string"}, {description="Glob pattern (*.lua) or Lua pattern (%.lua$)", name="pattern", param_type="string"}}, returns={{description="| nil List of matching paths, or nil if the root failed", return_type="{string}"}, {description="First error encountered, if any", return_type="string"}}, signature="(dir: string, pattern: string): {string} | nil, string"}, {description=" Recursively collect all files with their Unix permissions.\n Returns a map of relative paths to file information.\n If the root directory cannot be opened, returns nil plus the error.\n Failures below the root do not stop the collection; the first such\n error is returned alongside the results.", is_local=true, line=178, name="collect_all", params={{description="The directory to walk", name="dir", param_type="string"}}, returns={{description="| nil Map of relative paths to file information", return_type="{string:FileInfo}"}, {description="First error encountered, if any", return_type="string"}}, signature="(dir: string): {string: FileInfo} | nil, string"}, {is_local=true, line=182, name="do_walk", params={}, returns={}, signature="(base_dir: string, rel_base: string): boolean"}, {description=" Iterate over files matching a pattern.\n Returns an iterator that yields file paths. The fourth return value\n is a to-be-closed guard: a plain `for f in fs.files(dir) do ... end`\n loop adopts it as the loop's closing value (Lua 5.4), so directory\n handles are closed even when the loop exits early via break/error.\n If the root directory cannot be opened, returns nil plus the error —\n iterate the checked value: `for f in assert(fs.files(dir)) as fs.FileIter do`\n (assert passes all four returns through, keeping the closing guard;\n the cast only narrows the type, it does not drop return values).", is_local=true, line=0x0100, name="files", params={{description="The directory to search", name="dir", param_type="string"}, {description="Glob pattern (*.lua) - defaults to all files (*)", name="pattern", param_type="string"}}, returns={{description="| nil Iterator yielding file paths, or nil if the root could not be opened", return_type="function"}, {description="Error if the root directory could not be opened", return_type="string"}, {description="Unused (generic-for control slot)", return_type="nil"}, {description="Closing guard that releases open directory handles", return_type="any"}}, signature="(dir: string, pattern?: string): FileIter | nil, string, any, any"}, {is_local=true, line=276, name="close_all", params={}, returns={}, signature="()"}}, internal=true, module_doc=" Directory walking and file collection utilities.\n Provides recursive directory traversal, pattern-based file collection,\n and file iteration.", records={{description=" Handle for reading directory entries (internal).\n `read`'s second return is the dirent d_type (unix.DT_DIR / DT_REG /\n DT_LNK / ... / DT_UNKNOWN) where the filesystem supports it, letting\n callers that only need \"is this a director