ding its dashes\n @field missing {string} Options that required an argument but got none", fields={{"opts", "{Option}", ""}, {"args", "{string}", ""}, {"unknown", "{string}", ""}, {"missing", "{string}", ""}}, line=44, name="Result"}, {description=" A parser object for iterating through command-line options one at a time.\n Retained as a thin compatibility shim over `parse`; prefer `parse`.", fields={{"next", "function(self: Parser): string, string", " Get the next option, or nil when done. Unknown/missing options are\n reported as \"?\" with the offending option string as the second value."}, {"remaining", "function(self: Parser): {string}", " Get remaining non-option arguments."}, {"unknown", "function(self: Parser): {string}", " Get any unknown options encountered during parsing."}}, line=53, name="Parser"}, {fields={{"LongOpt", "LongOpt", " Type for defining long options"}, {"Option", "Option", " Type for a single recognized option"}, {"Result", "Result", " Type for the parse result"}, {"Parser", "Parser", " Type for the stateful parser"}, {"parse", "function(args: {string}, optstring: string, longopts?: {LongOpt}): Result | nil, string", " Parse a command-line argument vector in one shot"}, {"new", "function(args: {string}, optstring: string, longopts?: {LongOpt}): Parser", " Create a stateful parser (compatibility shim over parse)"}}, line=190, name="GetoptModule"}}}, ["cosmic.hash"]={examples={}, file="lib/cosmic/hash.tl", functions={{description=" Compute SHA-256 hash of data.\n Returns raw bytes (32 bytes).", is_local=true, line=43, name="sha256", params={{description="The data to hash", name="data", param_type="string"}}, returns={{description="The SHA-256 hash as raw bytes", return_type="string"}}, signature="(data: string): string"}, {description=" Compute SHA-256 hash of data and return as hex string.\n Returns a 64-character lowercase hex string.", is_local=true, line=51, name="sha256_hex", params={{description="The data to hash", name="data", param_ty