":1}\n", description=" Example_decode demonstrates JSON decoding", expected_output="{\"a\":1}\n", line=5, name="Example_decode"}, {body="\n  local json = require(\"cosmic.json\")\n  local result = json.encode({a = 1})\n  print(result)\n  -- Output:\n  -- {\"a\":1}\n", description=" Example_encode demonstrates JSON encoding", expected_output="{\"a\":1}\n", line=15, name="Example_encode"}, {body="\n  local json = require(\"cosmic.json\")\n  local result, err = json.decode(\"{invalid}\")\n  if err then\n    print(\"decode error: \" .. err)\n  end\n  -- Output:\n  -- decode error: illegal character\n", description=" Example_decode_error demonstrates error handling for invalid JSON", expected_output="decode error: illegal character\n", line=24, name="Example_decode_error"}, {body="\n  local json = require(\"cosmic.json\")\n  local result, err = json.encode(function() end)\n  if err then\n    print(\"encode error: \" .. err)\n  end\n  -- Output:\n  -- encode error: unsupported lua type\n", description=" Example_encode_error demonstrates error handling for unencodable values", expected_output="encode error: unsupported lua type\n", line=35, name="Example_encode_error"}}, file="lib/cosmic/json.tl", functions={{description=" Decode a JSON string into a Lua value.\n Converts JSON strings, numbers, booleans, arrays, and objects into their Lua equivalents.\n JSON `null` becomes nil, so null-valued object keys vanish and arrays\n containing null are truncated at the first null when re-encoded (see the\n module-level null policy above).", is_local=true, line=38, name="decode", params={{description="The JSON string to decode", name="str", param_type="string"}}, returns={{description="The decoded Lua value (table, string, number, boolean, or nil)", return_type="any"}, {description="Error message if decoding failed", return_type="string?"}}, signature="(str: string): any, string"}, {description=" Encode a Lua value as a JSON string.\n Converts Lua tables, strings, numbers, booleans, and nil into JSON format.\n NaN encodes as `null`, +/-Inf as `1e5000`/`-1e5000`; nil-valued table\n entries are absent (see the module-level null policy above).", is_local=true, line=51, name="encode", params={{description="The Lua value to encode", name="value", param_type="any"}, {description="pretty, sorted, indent, maxdepth", name="options", param_type="EncodeOptions?"}}, returns={{description="| nil The JSON string representation", return_type="string"}, {description="Error message if encoding failed", return_type="string?"}}, signature="(value: any, options?: EncodeOptions): string | nil, string"}}, module_doc=" JSON encoding and decoding utilities.\n Wraps cosmo.EncodeJson and cosmo.DecodeJson with convenient Teal-typed interface.\n\n NULL POLICY (lossy — read before round-tripping):\n Lua tables cannot hold nil values, so JSON `null` does not survive a\n decode/encode round-trip:\n - `{\"a\":null,\"b\":1}` decodes with `a` absent and re-encodes as `{\"b\":1}`.\n - `[1,null,2]` decodes with a hole at index 2; re-encoding sees a table\n   of length 1 and truncates to `[1]`.\n - NaN encodes as `null`; +/-Inf encodes as the out-of-range literal\n   `1e5000`/`-1e5000`, which this module decodes back to +/-Inf but\n   stricter JSON parsers may reject.\n If null-preserving round-trips matter, restructure the data (e.g. encode\n explicit sentinel values) rather than relying on this module.", records={{description=" Options accepted by encode(). All fields are optional.", fields={{"pretty", "boolean", " Format across multiple lines for readability (default false)."}, {"sorted", "boolean", " Sort object keys for deterministic output (default true). Setting\n sorted=false can speed up serialization when ordering is irrelevant."}, {"indent", "string", " Indentation string used when pretty is true (default \" \")."}, {"maxdepth", "number", " Maximum serializer recursion depth (default 64, max 32767)."}}, line=18, name="EncodeOptions"}, {fields={{"decode", "function(str: string): any, string", ""}, {"encode", "function(value: any, options?: EncodeOptions): string | nil, string", ""}}, line=69, name="JsonModule"}}}, ["cosmic.landlock"]={examples={{body="\n  local landlock = require(\"cosmic.landlock\")\n  if landlock.available() then\n    io.write(\"available\\n\")\n  else\n    io.write(\"not available\\n\")\n  end\n", description=" Example_available demonstrates the capability probe. Applications\n should gate box setup on available() so they degrade cleanly on\n kernels older than 5.13 and on non-Linux hosts. This example prints\n a different line depending on whether landlock is supported, so no\n output check is attached.", line=12, name="Example_available"}, {body="\n  local landlock = require(\"cosmic.landlock\")\n  local rx = landlock.READ | landlock.EXEC\n  local rw = landlock.RW\n  io.write(tostring(rx > 0) .. \" \" .. tostring(rw > 0) .. \"\\n\")\n  -- Output:\n  -- true true\n", description=" Example_masks demonstrates composing access-flag constants into rule\n masks. cosmic.landlock.READ / EXEC / WRITE / RW / ALL are bitmask\n integers; combine with `|`.", expected_output="true true\n", line=24, name="Example_masks"}, {body="\n  local spawn = require(\"cosmic.child\")\n  local cosmic = arg[-1]\n  local script = [[\nlocal ll = require(\"cosmic.landlock\")\nif not ll.available() then return end\nassert(ll.restrict{\n  rules = {\n    { path = \"/usr\", access = ll.READ | ll.EXEC },\n    { path = \"/tmp\", access = ll.RW },\n  },\n})\n]]\n  local h = spawn.spawn({cosmic, \"-e\", script})\n  local _ = (h as spawn.Handle):wait()\n", description=" Example_restrict demonstrates pinning the process to a read-only view\n of /usr plus read/write access to /tmp. After restrict returns,\n opening files outside the allowlist fails with EACCES. Runs in a\n subprocess because the restriction cannot be undone; no output check\n is attached because behavior depends on kernel support.", line=38, name="Example_restrict"}}, file="lib/cosmic/landlock.tl", functions={{description=" Per-ABI \"max access\" mask. Categories above the kernel's supported\n ABI MUST be stripped before create_ruleset or it returns EINVAL.", is_local=true, line=113, name="abi_mask", params={}, returns={}, signature="(abi_version: integer): integer"}, {description=" Returns the kernel's supported landlock ABI version (>= 1 when\n landlock is enabled). Returns nil + error on ENOSYS or non-Linux.", is_local=true, line=124, name="abi", params={}, returns={}, signature="(): integer | nil, string"}, {description=" True when abi() >= 1. Gate box setup on this.", is_local=true, line=133, name="available", params={}, returns={}, signature="(): boolean"}, {description=" Apply a path allowlist to the current thread and all its future\n children. Irreversible.\n Access outside the allowlist fails with EACCES after this returns.\n Access categories above the running kernel's ABI are stripped from\n `handled` automatically, so `cosmic.landlock.ALL` stays portable.\n The ruleset fd is always closed before return.\n Known gap: TRUNCATE is only handleable on landlock ABI >= 3, so on\n older kernels a restricted process can still truncate(2) files\n outside its allowlist. (Cosmopolitan's C unveil path plugs this with\n a seccomp filter; this module does not.) Pair with `cosmic.pledge`\n — truncate is governed by its \"wpath\" group — where that matters.", is_local=true, line=151, name="restrict", params={}, returns={}, signature="(opts: RestrictOptions): boolean, string"}, {is_local=true, line=161, name="fail", params={}, returns={}, signature="(msg: string): boolean, string"}}, module_doc=" Linux landlock filesystem sandbox.\n\n Landlock is an unprivileged, process-self-restricting filesystem\n sandbox. Any process (even running as a regular user) can narrow its\n own file access to a declared allowlist. Once applied, the\n restriction is inherited by children and cannot be relaxed — only\n further narrowed.\n\n Typical usage:\n\n     local ll = require(\"cosmic.landlock\")\n     if not ll.available() then return end\n     local ok, err = ll.restrict{\n       rules = {\n         { path = \"/usr\",  access = ll.READ | ll.EXEC },\n         { path = \"/tmp\",  access = ll.RW },\n       },\n     }\n\n Requires Linux >= 5.13. `available()` returns false on older kernels\n and non-Linux hosts; gate box setup on it. Pairs naturally with\n `cosmic.pledge` on Linux and is complementary to `cosmic.quicksand`\n network isolation.", records={{description=" A single path -> access-mask rule in a restrict() call.\n `access` is an OR of cosmic.landlock.* flag constants (READ, EXEC,\n WRITE_FILE, MAKE_REG, etc.) and must be a subset of the call's\n `handled` mask. When `path` is not a directory, directory-only\n rights are stripped automatically, so `access = READ` works on a\n regular file even though READ bundles READ_DIR.", fields={{"path", "string", ""}, {"access", "integer", ""}}, line=66, name="Rule"}, {description=" Options for `restrict`. `handled` narrows which access categories\n the sandbox controls (categories outside it are left unrestricted;\n defaults to cosmic.landlock.ALL). `rules` lists allowed paths.\n `no_new_privs` defaults to true (sets PR_SET_NO_NEW_PRIVS before the\n restrict, which the kernel requires unless the caller already set it\n or holds CAP_SYS_ADMIN).", fields={{"handled", "integer", ""}, {"rules", "{Rule}", ""}, {"no_new_privs", "boolean", ""}}, line=77, name="RestrictOptions"}, {fields={{"EXECUTE", "integer", ""}, {"WRITE_FILE", "integer", ""}, {"READ_FILE", "integer", ""}, {"READ_DIR", "integer", ""}, {"REMOVE_DIR", "integer", ""}, {"REMOVE_FILE", "integer", ""}, {"MAKE_CHAR", "integer", ""}, {"MAKE_DIR", "integer", ""}, {"MAKE_REG", "integer", ""}, {"MAKE_SOCK", "integer", ""}, {"MAKE_FIFO", "integer", ""}, {"MAKE_BLOCK", "integer", ""}, {"MAKE_SYM", "integer", ""}, {"REFER", "integer", ""}, {"TRUNCATE", "integer", ""}, {"READ", "integer", ""}, {"EXEC", "integer", ""}, {"WRITE", "int