urce_dir", "string", ""}, {"build_dir", "string", ""}, {"cosmic_bin", "string", ""}}, line=9, name="Config"}, {description=" Classified project files.", fields={{"sources", "{string}", ""}, {"tests", "{string}", ""}, {"examples", "{string}", ""}}, line=16, name="Project"}, {fields={{"scan", "function(dir: string): Project", ""}, {"generate", "function(project: Project, config?: Config): string", ""}, {"run", "function(dir?: string, target?: string): boolean, string", ""}}, line=224, name="MakeModule"}}}, ["cosmic.net"]={examples={{body="\n  local net = require(\"cosmic.net\")\n  local srv, port, err = net.listen_tcp(0x7f000001, 0)\n  assert(srv, err)\n  assert(port > 0)\n  local srv = srv as net.Socket\n\n  local client, cerr = net.connect_tcp(0x7f000001, port)\n  assert(client, cerr)\n  local client = client as net.Socket\n\n  local conn, _, _, aerr = srv:accept()\n  assert(conn, aerr)\n  local conn = conn as net.Socket\n\n  client:send(\"hello\")\n  local msg = conn:recv()\n  conn:send(\"echo: \" .. (msg as string))\n  print(client:recv())\n\n  client:close()\n  conn:close()\n  srv:close()\n  -- Output:\n  -- echo: hello\n", description=" Example_echo demonstrates a minimal TCP echo exchange on loopback:\n listen on an OS-assigned port, connect, accept, echo one message back", expected_output="echo: hello\n", line=5, name="Example_echo"}, {body="\n  local net = require(\"cosmic.net\")\n  local srv, port, err = net.listen_tcp(0x7f000001, 0)\n  assert(srv, err)\n  local srv = srv as net.Socket\n\n  local client = net.connect_tcp(0x7f000001, port) as net.Socket\n  local conn = srv:accept() as net.Socket\n\n  client:close()\n  local data = conn:recv()\n  print(data == \"\" and \"eof\" or \"data\")\n\n  conn:close()\n  srv:close()\n  -- Output:\n  -- eof\n", description=" Example_recv_eof demonstrates end-of-stream detection: recv returns an\n empty string (not nil) when the peer closes the connection", expected_output="eof\n", line=34, name="Example_recv_eof"}}, file=