" Create and enter a new user namespace in the current thread.\n Equivalent to `unshare(CLONE_NEWUSER)`; grants the thread the\n capabilities needed to unshare a network namespace unprivileged.\n unshare is irreversible for the calling thread, so run it in a\n subprocess when the original namespace must be preserved.", is_local=true, line=125, name="unshare_user", params={}, returns={{description="true on success", return_type="boolean"}, {description="error message on failure", return_type="string?"}}, signature="(): boolean, string"}, {description=" Create and enter a new network namespace in the current thread.\n Equivalent to `unshare(CLONE_NEWNET)`; requires either root or\n unshare_user() beforehand.", is_local=true, line=137, name="unshare", params={}, returns={{description="true on success", return_type="boolean"}, {description="error message on failure", return_type="string?"}}, signature="(): boolean, string"}, {description=" Bring `name` up in the current net namespace (reads flags, sets\n IFF_UP, writes them back). Idempotent.", is_local=true, line=149, name="bring_up", params={{description="interface name (e.g. \"lo\")", name="name", param_type="string"}}, returns={{description="true on success", return_type="boolean"}, {description="error message on failure", return_type="string?"}}, signature="(name: string): boolean, string"}, {description=" Bring `name` down in the current net namespace. Idempotent.", is_local=true, line=162, name="bring_down", params={{description="interface name", name="name", param_type="string"}}, returns={{description="true on success", return_type="boolean"}, {description="error message on failure", return_type="string?"}}, signature="(name: string): boolean, string"}, {description=" Close a file descriptor previously returned by open().", is_local=true, line=175, name="close", params={{description="file descriptor", name="fd", param_type="integer"}}, returns={{description="true on success", return_type="boolean"}, {description="error message on failure", return_type="string?"}}, signature="(fd: integer): boolean, string"}}, internal=true, module_doc=" Linux network-namespace primitives.\n\n Typed implementation over cosmo.unix: namespace fds, setns/unshare,\n and SIOC* interface-flag ioctls for bringing loopback up inside a\n fresh namespace. All calls are Linux-only and return cosmic's\n value,string error shape.\n\n Typical flow in a forked child that wants to live in its own\n network namespace with only loopback reachable:\n\n     local ns = require(\"cosmic.quicksand.netns\")\n     assert(ns.unshare())\n     assert(ns.bring_up(\"lo\"))\n\n To enter an existing child's namespace from the parent:\n\n     local fd = assert(ns.open(child_pid))\n     assert(ns.enter(fd))\n     ns.close(fd)", records={{fields={{"open", "function(pid: integer): integer | nil, string", ""}, {"enter", "function(fd: integer): boolean, string", ""}, {"unshare_user", "function(): boolean, string", ""}, {"unshare", "function(): boolean, string", ""}, {"bring_up", "function(name: string): boolean, string", ""}, {"bring_down", "function(name: string): boolean, string", ""}, {"get_flags", "function(name: string): integer | nil, string", ""}, {"set_flags", "function(name: string, flags: integer): boolean, string", ""}, {"close", "function(fd: integer): boolean, string", ""}}, line=181, name="NetnsModule"}}}, ["cosmic.quicksand.proc"]={examples={{body="\n  local proc = require(\"cosmic.quicksand.proc\")\n  io.write(table.concat(proc.DEFAULT_SIGNALS, \",\") .. \"\\n\")\n  -- Output:\n  -- SIGINT,SIGTERM,SIGHUP\n", description=" Example_default_signals shows the default signal set that\n become_init() forwards to the main process.", expected_output="SIGINT,SIGTERM,SIGHUP\n", line=5, name="Example_default_signals"}, {body="\n  local proc = require(\"cosmic.quicksand.proc\")\n  local ok = proc.drop_privs(nil, nil)\n  io.write(tostring(ok) .. \"\\n\")\n  -- Output:\n  -- true\n", description=" Example_drop_privs_noop demonstrates that drop_privs(nil) is a\n no-op — useful when the caller wants to skip privilege dropping\n without branching.", expected_output="true\n", line=15, name="Example_drop_privs_noop"}, {body="\n  local spawn = require(\"cosmic.child\")\n  local cosmic = arg[-1]\n  local script = [[\nlocal proc = require(\"cosmic.quicksand.proc\")\nassert(proc.no_new_privs())\n]]\n  local h = spawn.spawn({cosmic, \"-e\", script})\n  local hh = h as spawn.Handle\n  hh:wait()\n", description=" Example_no_new_privs_subprocess applies PR_SET_NO_NEW_PRIVS in a\n subprocess because the bit cannot be cleared once set. No output\n check: behavior depends on kernel support.", line=26, name="Example_no_new_privs_subprocess"}}, file="lib/cosmic/quicksand/proc.tl", functions={{description=" Set PR_SET_NO_NEW_PRIVS on the current process. Irreversible;\n inherited by children. Required to install seccomp filters\n without CAP_SYS_ADMIN and to neutralize setuid/setgid/file-caps\n across execve.", is_local=true, line=44, name="no_new_privs", params={}, returns={{description="true on success", return_type="boolean"}, {description="error message on failure", return_type="string?"}}, signature="(): boolean, string"}, {description=" Drop to (uid, gid) and clear capabilities. If uid is nil, no-op.\n If uid == 0, keep root but still clear caps (\"root without\n superpowers\"). gid defaults to uid when nil.\n Performs PR_SET_KEEPCAPS, setresgid, setresuid, capset(0,0,0) in\n order. PR_SET_KEEPCAPS preserves capabilities across the setuid so\n they can be cleared explicitly afterwards; all three of real /\n effective / saved ids are switched so there is no path back. On\n non-Linux hosts where capset is ENOSYS, returns success since\n there are no Linux caps to clear.", is_local=true, line=65, name="drop_privs", params={{description="target uid (nil = no-op)", name="uid", param_type="integer?"}, {description="target gid (defaults to uid)", name="gid", param_type="integer?"}}, returns={{description="true on success", return_type="boolean"}, {description="error message on failure", return_type="string?"}}, signature="(uid: integer, gid: integer): boolean, string"}, {description=" Open `path` write-only and write `data` in one shot. On failure\n returns false plus the binding's error string and numeric errno,\n so callers can classify the failure (e.g. a benign ENOENT).", is_local=true, line=87, name="write_file", params={}, returns={}, signature="(path: string, data: string): boolean, string, integer"}, {description=" Write uid_map / setgroups / gid_map for the current process so\n that inner uid 0 maps to the host `uid` (and inner gid 0 to host\n `gid`). Must be called after unshare(CLONE_NEWUSER) and before any\n operation that requires a valid identity (setresuid, capset,\n mount, ...). Equivalent to:\n     echo \"0 $uid 1\" > /proc/self/uid_map\n     echo \"deny\"     > /proc/self/setgroups   # kernel >= 3.19\n     echo \"0 $gid 1\" > /proc/self/gid_map\n The setgroups \"deny\" write must precede the gid_map write on\n kernels >= 3.19; unprivileged writers are rejected from gid_map\n otherwise. On kernels without the setgroups proc file the write\n fails with ENOENT, which is benign and ignored.", is_local=true, line=115, name="setup_userns_maps", params={{description="host uid to map to inner 0 (default: euid)", name="uid", param_type="integer?"}, {description="host gid to map to inner 0 (default: egid)", name="gid", param_type="integer?"}}, returns={{description="true on success", return_type="boolean"}, {description="error message on failure", return_type="string?"}}, signature="(uid: integer, gid: integer): boolean, string"}, {description=" Allocate a one-shot pipe-backed barrier. After fork, each side\n drops the end it won't use, then uses the end it kept:\n     local b = assert(proc.barrier())\n     local pid = assert(unix.fork())\n     if pid == 0 then\n       b:drop_read()\n       -- ... unshare/setup ...\n       b:signal()\n       unix.execvp(cmd[1], cmd)\n     end\n     b:drop_write()\n     b:wait()\n signal() writes one byte and closes the write end. wait() reads\n one byte (EOF counts as signaled, which propagates child crashes)\n and closes the read end. drop_read() / drop_write() are\n idempotent.", is_local=true, line=152, name="barrier", params={}, returns={{description="barrier object on success", return_type="Barrier?"}, {description="error message on failure", return_type="string?"}}, signature="(): Barrier | nil, string"}, {description=" Enter a new PID namespace and fork a child that becomes PID 1\n inside it. Returns the child's pid to the parent and 0 to the\n child (mirroring unix.fork), or nil + error on failure.\n unshare(CLONE_NEWPID) does NOT move the calling process into the\n new namespace — only its future children are born there, and the\n first such child is PID 1. Only that child can mount a private\n procfs that shows just the sandbox's own processes; mounting from\n the parent leaks all host processes. Typical flow: the child\n mounts /proc then execs the workload, while the parent runs\n become_init() so the child's exit status is reaped.", is_local=true, line=203, name="fork_pidns", params={}, returns={{description="child pid in the parent, 0 in the child", return_type="integer?"}, {description="error message on failure", return_type="string?"}}, signature="(): integer | nil, string"}, {description=" Run a PID-1 supervisor loop. Forwards signals in opts.signals\n (default SIGINT/SIGTERM/SIGHUP) to main_pid, reaps zombies, and\n when main_pid exits kills + reaps all opts.sidecars. If a sidecar\n exits first, kills main_pid (after invoking opts.on_sidecar_exit,\n if set) and returns 1. EINTR during wait is handled internally.\n Returns an integer exit code suitable for os.exit():\n   0..255         main_pid exited with that status\n   128 + signum   main_pid was terminated by signum\n   1              unexpected supervisor failure, or a sidecar\n                  exited before main_pid\n Not thread-safe: uses process-wide sigaction.", is_local=true, line=230, name="become_init", params={{description="pid of the main user-visible child", name="main_pid", param_type="integer"}, {description="sidecar pids, signal set, exit hook", name="opts", param_type="InitOptions?"}}, returns={{description="exit code for os.exit()", return_type="integer"}}, signature="(main_pid: integer, opts: InitOptions): integer"}, {is_local=true, line=245, name="kill_and_reap", params={}, returns={}, signature="(pid: integer)"}}, internal=true, module_doc=" Process-setup primitives for box assembly.\n\n Typed implementation over cosmo.unix for the \"after fork, before\n exec\" work of a boxed child plus the PID-1 supervisor loop used\n by netns + proxy sidecar topologies. Linux-only.\n\n no_new_privs, drop_privs: call before execve in the boxed child.\n setup_userns_maps: write uid_map / setgroups / gid_map after\n   unshare(CLONE_NEWUSER) so the child has a valid identity.\n barrier: synchronize parent/child across unshare + /proc/<pid>/ns/\n   observation windows.\n fork_pidns: enter a fresh PID namespace and fork its PID 1.\n become_init: run a PID-1 loop that forwards signals, reaps zombies,\n   and coordinates main-process / sidecar lifecycles.", records={{description=" One-shot pipe-backed barrier for cross-process fork+unshare\n synchronization.", fields={{"signal", "function(self: Barrier)", ""}, {"wait", "function(self: Barrier)", ""}, {"drop_read", "function(self: Barrier)", ""}, {"drop_write", "function(self: Barrier)", ""}}, line=20, name="Barrier"}, {description=" Options for become_init().", fields={{"sidecars", "{integer}", ""}, {"signals", "{string}", ""}, {"on_sidecar_exit", "function(pid: integer, ws: integer)", ""}}, line=28, name="InitOptions"}, {fields={{"no_new_privs", "function(): boolean, string", ""}, {"drop_privs", "function(uid: integer, gid: integer): boolean, string", ""}, {"setup_userns_maps", "function(uid: integer, gid: integer): boolean, string", ""}, {"barrier", "function(): Barrier | nil, string", ""}, {"fork_pidns", "function(): integer | nil, string", ""}, {"become_init", "function(main_pid: integer, opts: InitOptions): integer", ""}, {"DEFAULT_SIGNALS", "{string}", ""}}, line=287, name="ProcModule"}}}, ["cosmic.quicksand.proxy"]={examples={{body="\n  local quicksand = require(\"cosmic.quicksand\")\n  if not quicksand.capabilities().linux then\n    io.write(\"not linux\\n\")\n    return\n  end\n  local proxy = require(\"cosmic.quicksand.proxy\")\n  local handle, err = proxy.start({\n      bind_ip = 0x7f000001,\n      bind_port = 0,\n      allowed_hosts = {\n        [\"api.example.com:443\"] = {},\n        [\"internal.example.com:80\"] = {\n          type = \"bearer\",\n          token = \"redacted\",\n        },\n      },\n      log_level = \"quiet\",\n    })\n  if not handle then\n    io.write(\"proxy start failed: \" .. tostring(err) .. \"\\n\")\n    return\n  end\n  io.write(\"listening\\n\")\n  local h = handle as proxy.ProxyHandle\n  h:stop()\n", description=" Example_start_stop demonstrates the common pattern: start the\n proxy on an ephemeral port, query the bound port, then tear it\n down with stop() (which SIGTERMs and waitpids the listener).", line=6, name="Example_start_stop"}}, file="lib/cosmic/quicksand/proxy.tl", functions={{is_local=true, line=58, name="now_ms", params={}, returns={}, signature="(): integer"}, {description=" Send SIGTERM and reap the proxy child, escalating to SIGKILL when\n it hasn't exited within timeout_ms (default 5000) so a hung worker\n can't wedge the supervisor. Idempotent: once reaped (pid == 0),\n short-circuits without re-signalling — a reused pid must never\n receive a stray signal. Always returns true; signal/wait failures\n are swallowed since the post-condition (child no longer ours) is\n reached regardless.", is_local=true, line=70, name="handle_stop", params={}, returns={}, signature="(self: ProxyHandle, timeout_ms?: integer): boolean"}, {description=" Non-blocking health check: true while the proxy child is still\n running, false once it has exited. On observing an exit, reaps\n the zombie and clears pid to 0 so later calls short-circuit\n without racing pid reuse.", is_local=true, line=95, name="handle_alive", params={}, returns={}, signature="(self: ProxyHandle): boolean"}, {description=" Fork a proxy listener into a child process. The allowlist is\n validated before forking, so schema errors surface here. The\n parent blocks until the child has bound and listened (the bound\n port comes back over a pipe), so handle.port is valid immediately\n on return.", is_local=true, line=114, name="start", params={{description="allowlist + binding + logging config", name="opts", param_type="ProxyOptions"}}, returns={{description="handle with pid, port, stop(), alive()", return_type="ProxyHandle?"}, {description="error message on failure", return_type="string?"}}, signature="(opts: ProxyOptions): ProxyHandle | nil, string"}}, internal=true, module_doc=" Allowlist HTTP CONNECT + plain-HTTP proxy for sandboxed egress.\n\n The proxy binds inside a child's network namespace (the only thing\n the sandboxed workload can reach) and dials upstream in a\n different namespace, so a netns-isolated child can reach a narrow\n set of approved hosts and nothing else. Non-public upstream IPs\n are refused after DNS resolution (SSRF protection), and per-dial\n resolution is deadline-bounded so a tarpitting resolver can't\n wedge a worker.\n\n start(opts) validates the allowlist, forks the listener into a\n child process, and returns a ProxyHandle with the bound pid and\n port. handle:stop() sends SIGTERM (escalating to SIGKILL after a\n timeout) and reaps the child; handle:alive() is a non-blocking\n liveness check. Implementation lives in cosmic.quicksand.proxy.*\n (rules, http, dial, serve); advanced callers needing a non-forking\n server can use cosmic.quicksand.proxy.serve directly.\n\n Rule schema (allowed_hosts):\n\n   {\n     [\"api.example.com:443\"]     = {},                  -- pass-through\n     [\"*.githubusercontent.com\"] = {},                  -- any port\n     [\"internal.example.com:80\"] = { type = \"bearer\",\n                                     token = \"...\" },   -- inject header\n     [\"legacy.example.com:80\"]   = { type = \"basic\",\n                                     username = \"u\",\n                                     password = \"p\" },\n     [\"api.example.com:80\"]      = { type = \"header\",\n                                     header_name = \"x-api-key\",\n                                     header_value = \"...\" },\n   }\n\n Host specs: `host`, `host:port`, `host:*`, `*.suffix`,\n `*.suffix:port`. An empty rule table is pass-through (allow, no\n header injection). Header injection happens on plain HTTP only;\n CONNECT is opaque. Malformed rules (unknown `type`, missing\n fields) make start() fail loudly instead of degrading to\n pass-through.", records={{description=" Returned by start(). `stop()` sends SIGTERM and reaps the\n listener, escalating to SIGKILL after `timeout_ms` (default 5000).\n It is idempotent: once the child has been reaped, subsequent calls\n are no-ops. `alive()` is a non-blocking liveness check.", fields={{"pid", "integer", ""}, {"port", "integer", ""}, {"stop", "function(self: ProxyHandle, timeout_ms?: integer): boolean", ""}, {"alive", "function(self: ProxyHandle): boolean", ""}}, line=51, name="ProxyHandle"}, {fields={{"start", "function(opts: ProxyOptions): ProxyHandle | nil, string", ""}}, line=178, name="ProxyModule"}}}, ["cosmic.quicksand.proxy.dial"]={examples={}, file="lib/cosmic/quicksand/proxy/dial.tl", functions={{description=" Resolve `host` to an IPv4 integer. Literal IPs parse immediately;\n otherwise the lookup goes through `resolver` (default\n cosmo.ResolveIp, which uses the system resolver in the *current*\n netns — call after setns() to the upstream namespace).\n When `timeout_ms` is non-nil the lookup runs in a forked helper\n and the parent polls the result pipe; past the deadline the helper\n is SIGKILL'd and (nil, \"resolve timeout\") is returned, so a\n hostile or tarpitting resolver can't wedge a per-connection worker\n past its budget. Literal IPs skip the fork entirely.\n   to cosmo.ResolveIp", is_local=true, line=31, name="resolve", params={{description="hostname or literal IPv4", name="host", param_type="string"}, {description="resolution deadline (nil = unbounded)", name="timeout_ms", param_type="integer?"}, {description="test seam returning (ip, err); defaults", name="resolver", param_type="function?"}}, returns={{description="IPv4 address as an integer", return_type="integer?"}, {description="error message on failure", return_type="string?"}}, signature="(host: string, timeout_ms: integer,\n    resolver: function(string): integer, any): integer | nil, string"}, {description=" Open a TCP connection to (host, port) in the namespace identified\n by `upstream_ns_fd`, falling back to the current namespace when\n the fd is nil. `resolve_timeout_ms` (optional) bounds DNS\n resolution per dial.\n Non-public IPs are refused after resolution to prevent SSRF: this\n covers loopback (127/8), link-local (169.254/16) including the\n cloud metadata endpoint, RFC1918, CGNAT (100.64/10), 0.0.0.0/8,\n and other reserved ranges — on both CONNECT and plain-HTTP paths.\n The upstream socket is SOCK_CLOEXEC so it can't leak into an\n exec'd child via an accidental fork/exec ordering change.", is_local=true, line=108, name="dial", params={{description="hostname or literal IPv4", name="host", param_type="string"}, {description="TCP port", name="port", param_type="integer"}, {description="netns fd to dial in (nil = current)", name="upstream_ns_fd", param_type="integer?"}, {description="per-dial DNS deadline", name="resolve_timeout_ms", param_type="integer?"}}, returns={{description="connected socket fd", return_type="integer?"}, {description="error message on failure", return_type="string?"}}, signature="(host: string, port: integer, upstream_ns_fd: integer,\n    resolve_timeout_ms: integer): integer | nil, string"}}, internal=true, module_doc=" Upstream dialing for the cosmic.quicksand.proxy egress proxy:\n bounded DNS resolution and cross-namespace TCP connects with SSRF\n protection.\n\n The proxy listens inside a child network namespace and dials\n upstream in a different one (typically the parent's); dial() joins\n the upstream namespace with setns() first, so it must run in a\n per-connection fork where the namespace switch can't leak into\n other connections.", records={{fields={{"resolve", "function(string, integer, function(string): (integer, any)):", ""}, {"dial", "function(string, integer, integer, integer): integer | nil, string", ""}}, line=131, name="DialModule"}}}, ["cosmic.quicksand.proxy.http"]={examples={}, file="lib/cosmic/quicksand/proxy/http.tl", functions={{description=" Read from `fd` until \"\\r\\n\\r\\n\" or EOF. Returns (header_block,\n leftover_after_block). Bounds the read to `max` bytes (default\n 65536) to avoid memory blowups from junk input.", is_local=true, line=34, name="read_headers", params={}, returns={}, signature="(fd: integer, max: integer): string | nil, string"}, {description=" Send all of `data` on `fd`, resuming short writes via the send()\n offset parameter (no tail-substring reallocation).", is_local=true, line=52, name="send_all", params={}, returns={}, signature="(fd: integer, data: string): boolean, string"}, {description=" Read exactly `n` bytes from `fd`, given an optional already-\n buffered prefix. Returns (body, leftover_beyond_n).", is_local=true, line=66, name="read_body", params={}, returns={}, signature="(fd: integer, n: integer, prefix: string):"}, {description=" Parse an HTTP request line \"METHOD TARGET HTTP/x.y\\r\\n\". Returns\n (method, target, version) or nil.", is_local=true, line=80, name="parse_request_line", params={}, returns={}, signature="(line: string): string | nil, string, string"}, {description=" Parse a CONNECT target \"host:port\". Returns (host, port) or nil.", is_local=true, line=86, name="parse_connect_target", params={}, returns={}, signature="(t: string): string | nil, integer"}, {description=" Parse an absolute URI \"http://host[:port]/path\" (proxies receive\n absolute-form per RFC 7230 5.3.2). Returns (scheme, host, port,\n path) with the scheme's default port and \"/\" filled in, or nil.", is_local=true, line=95, name="parse_absolute_uri", params={}, returns={}, signature="(t: string): string | nil, string, integer, string"}, {description=" Parse a header block (everything after the request line, up to the\n blank \\r\\n) into a list of {orig_name, lower_name, value} triples.", is_local=true, line=114, name="parse_headers", params={}, returns={}, signature="(block: string): {Header}"}, {description=" First header value for `lower_name` (case-insensitive), or nil.", is_local=true, line=131, name="header_get", params={}, returns={}, signature="(headers: {Header}, lower_name: string): string | nil"}, {description=" Content-Length from a parsed header list; 0 if absent.", is_local=true, line=139, name="content_length", params={}, returns={}, signature="(headers: {Header}): integer"}, {description=" Construct the forwarded HTTP request: method + origin-form target\n + HTTP/1.1, Host rewritten to spec.host_hdr, hop-by-hop headers\n stripped, our injected auth header replacing any client-supplied\n one of the same name, and Connection: close.", is_local=true, line=177, name="rebuild_request", params={}, returns={}, signature="(spec: ForwardSpec): string"}, {description=" Bidirectional byte pump between two TCP fds. Returns when both\n sides hit EOF or one side errors. Single-process: multiplexes with\n unix.poll, and issues shutdown(SHUT_WR) toward the peer on each\n half-close so it sees clean EOF.", is_local=true, line=211, name="pump", params={}, returns={}, signature="(a: integer, b: integer)"}, {is_local=true, line=221, name="close_side", params={}, returns={}, signature="(fd: number, peer: integer)"}}, internal=true, module_doc=" HTTP/1.1 wire helpers for the cosmic.quicksand.proxy egress proxy:\n request-line / header / target parsing, bounded socket reads,\n short-write-safe sends, request rewriting for upstream forwarding,\n and the bidirectional CONNECT byte pump.\n\n Parsing functions are pure; the I/O helpers operate on raw socket\n fds via cosmo.unix and return cosmic's value,string error shape.", records={{description=" Everything needed to rewrite a client request for the upstream:\n request line pieces, parsed headers, optional body, the Host\n header value, and an optional auth header to inject.", fields={{"method", "string", ""}, {"path", "string", ""}, {"headers", "{Header}", ""}, {"body", "string", ""}, {"host_hdr", "string", ""}, {"inject_name", "string", ""}, {"inject_value", "string", ""}}, line=163, name="ForwardSpec"}, {fields={{"DENY", "string", ""}, {"BAD_REQUEST", "string", ""}, {"LENGTH_REQUIRED", "string", ""}, {"UPSTREAM_FAIL", "string", ""}, {"read_headers", "function(fd: integer, max: integer): string | nil, string", ""}, {"send_all", "function(fd: integer, data: string): boolean, string", ""}, {"read_body", "function(fd: integer, n: integer, prefix: string): string | nil, string", ""}, {"parse_request_line", "function(line: string): string | nil, string, string", ""}, {"parse_connect_target", "function(t: string): string | nil, integer", ""}, {"parse_absolute_uri", "function(t: string): string | nil, string, integer, string", ""}, {"parse_headers", "function(block: string): {Header}", ""}, {"header_get", "function(headers: {Header}, lower_name: string): string | nil", ""}, {"content_length", "function(headers: {Header}): integer", ""}, {"rebuild_request", "function(spec: ForwardSpec): string", ""}, {"pump", "function(a: integer, b: integer)", ""}}, line=248, name="HttpModule"}}}, ["cosmic.quicksand.proxy.rules"]={examples={}, file="lib/cosmic/quicksand/proxy/rules.tl", functions={{description=" Split a host-spec into (\"host\", port or nil). A missing port,\n \":*\", or \":\" all mean \"any port\". Hosts compare case-insensitively.\n A malformed port is *not* handled here — callers must validate keys\n with validate_key first, or a typo silently widens to \"any port\".", is_local=true, line=40, name="parse_rule", params={}, returns={}, signature="(key: string): string, integer"}, {description=" Validate an allowlist *key* (host-spec). Returns nil on success or a\n human-readable error. The port component, when present, must be `*`,\n empty, or a decimal integer in 1..65535 — otherwise `tonumber`\n returns nil and parse_rule would silently widen the rule to \"any\n port\" (fail-open in a security boundary). A stray extra colon\n (`\"host:5432:6\"`) trips the digit check for the same reason. The\n optional `*.` wildcard prefix is stripped before checking.", is_local=true, line=58, name="validate_key", params={}, returns={}, signature="(key: string): string"}, {description=" Validate a single allowlist rule. Returns nil on success, or a\n human-readable error string. Bare pass-through values (nil, true,\n {}) are accepted as \"allow, no auth injection\"; a table with a\n `type` field must use a known type and carry the fields that\n auth_header() would dereference. Unknown non-type fields are\n ignored (forward compatibility).", is_local=true, line=82, name="validate_rule", params={}, returns={}, signature="(key: string, rule: any): string"}, {description=" Validate every rule in an allowlist. Returns true, or false plus\n the first error found.", is_local=true, line=124, name="validate", params={}, returns={}, signature="(allowed_hosts: {string: any}): boolean, string"}, {description=" Build a lookup Index from an allowlist table. Wildcard entries\n are stored with a leading \".\" and matched at the tail of the\n candidate host, in insertion order.", is_local=true, line=137, name="index", params={}, returns={}, signature="(allowed_hosts: {string: any}): Index"}, {description=" Look up a (host, port) pair. Returns the rule value on a hit, or\n nil. Exact-host matches win over suffix patterns; suffix patterns\n return the first hit in insertion order.", is_local=true, line=161, name="match", params={}, returns={}, signature="(idx: Index, host: string, port: integer): any"}, {description=" Build the auth header a rule injects on plain-HTTP requests.\n Returns (name, value), or nil for pass-through rules.", is_local=true, line=179, name="auth_header", params={}, returns={}, signature="(rule: any): string | nil, string"}}, internal=true, module_doc=" Allowlist rule parsing, validation, and matching for the\n cosmic.quicksand.proxy egress proxy.\n\n An allowlist maps host-spec strings to rule values:\n\n   host              any port on exact host\n   host:port         exact host + exact port\n   host:*            any port on exact host (explicit)\n   *.suffix          any host ending in \".suffix\", any port\n   *.suffix:port     any host ending in \".suffix\", exact port\n\n Rule values: an empty table (or true) means \"allow, no auth\n injection\". A table with a `type` field of \"bearer\", \"basic\", or\n \"header\" injects the corresponding header on plain-HTTP requests\n (CONNECT tunnels are opaque; the rule still gates the allowlist).\n validate() rejects unknown types and missing fields loudly — a\n typo'd rule silently degrading to pass-through would strip auth\n from an otherwise-authenticated egress path.", records={{description=" One wildcard (\"*.suffix\") allowlist entry. `port` nil = any port.", fields={{"suffix", "string", ""}, {"port", "integer", ""}, {"rule", "any", ""}}, line=22, name="SuffixEntry"}, {description=" Fast lookup structure built from an allowlist by index().\n exact[host][port] and exact[host][\"*\"] hold exact-host rules;\n suffix is walked in insertion order for \"*.suffix\" patterns.", fields={{"exact", "{string: {any: any}}", ""}, {"suffix", "{Suffix