tring", ""}, {"token", "string", ""}, {"username", "string", ""}, {"password", "string", ""}, {"header_name", "string", ""}, {"header_value", "string", ""}}, line=35, name="ProxyRule"}, {description=" Options for start() / new().", fields={{"bind_ip", "integer", ""}, {"bind_port", "integer", ""}, {"allowed_hosts", "{string: ProxyRule}", ""}, {"upstream_ns_fd", "integer", ""}, {"log_level", "string", ""}, {"log_format", "string", ""}, {"log_file", "string", ""}, {"accept_backlog", "integer", ""}, {"resolve_timeout_ms", "integer", ""}, {"on_log", "function({string: any})", ""}}, line=35, name="ProxyOptions"}, {fields={{"new", "function(opts: ProxyOptions): Server | nil, string", ""}}, line=35, name="ServeModule"}}}, ["cosmic.quicksand.types"]={examples={}, file="lib/cosmic/quicksand/types.tl", functions={}, internal=true, module_doc=" Shared record and enum types for the cosmic.quicksand family.\n\n One definition each for the policy records that cross module\n boundaries (the Box schema, the host Capabilities report), so the\n umbrella, the Box builder, and the fork/exec orchestrator all name\n the same nominal types instead of threading `{string: any}` maps.\n Type-only: the module value carries no functions.", records={{description=" A single allowlist rule for `net.allow`. Mirrors\n cosmic.quicksand.proxy.ProxyRule (whose looser runtime schema is\n validated by proxy.start) — empty table = pass-through.", fields={{"type", "NetRuleType", ""}, {"token", "string", ""}, {"username", "string", ""}, {"password", "string", ""}, {"header_name", "string", ""}, {"header_value", "string", ""}}, line=27, name="NetRule"}, {fields={{"proxy_env", "boolean", ""}, {"allow", "{string: NetRule}", ""}, {"log_level", "LogLevel", ""}, {"resolve_timeout_ms", "integer", ""}}, line=36, name="NetOptions"}, {fields={{"no_new_privs", "boolean", ""}, {"uid", "integer", ""}, {"gid", "integer", ""}, {"pledge", "string", ""}, {"drop_caps", "boolean", ""}, {"keep_caps", "{string}", ""}}, line=49,