am_type="number?"}}, returns={{description="The compiled regex, or nil on error", return_type="Regex?"}, {description="Error message if compilation failed", return_type="string?"}}, signature="(pattern: string, flags?: number): Regex | nil, string"}, {description=" Search for pattern match in text (convenience function).\n Compiles pattern on each call - use compile() for repeated searches.\n Uses POSIX extended syntax by default.\n On a match, returns the matched substring plus a table of the\n parenthesized capture groups (an empty table when the pattern has no\n groups, \"\" for groups that did not participate). A no-match returns\n nil with no error; a bad pattern or an engine failure returns\n nil, nil, err.", is_local=true, line=54, name="search", params={{description="The regex pattern to search for", name="pattern", param_type="string"}, {description="The text to search in", name="text", param_type="string"}, {description="Optional compile flags: BASIC, ICASE, NEWLINE, NOSUB", name="flags", param_type="number?"}}, returns={{description="| nil The matched substring, or nil on no match or error", return_type="string"}, {description="| nil Capture groups on match", return_type="{string}"}, {description="| nil Error message if compilation or the engine failed", return_type="string"}}, signature="(pattern: string, text: string, flags?: number): string | nil, {string} | nil, string | nil"}, {description=" Check if pattern matches anywhere in text.\n Convenience function that returns boolean instead of matched text.\n Named test (not match) to avoid confusion with Lua's string.match,\n which returns the matched text.", is_local=true, line=81, name="test", params={{description="The regex pattern to match", name="pattern", param_type="string"}, {description="The text to search in", name="text", param_type="string"}, {description="Optional compile flags: BASIC, ICASE, NEWLINE, NOSUB", name="flags", param_type="number?"}}, returns={{description="True if pattern matches