urns={{description="Module name, or nil if not found", return_type="string"}}, signature="(err: string): string | nil"}, {description=" Enhanced require function that provides helpful suggestions.", is_local=true, line=214, name="enhanced_require", params={{description="Module name to require", name="name", param_type="string"}}, returns={{description="The loaded module", return_type="any"}}, signature="(name: string): any"}, {description=" Install enhanced require globally.\n Call this early in startup to enable helpful error messages.", is_local=true, line=232, name="install", params={}, returns={}, signature="()"}, {description=" Restore original require.\n Useful for testing or disabling enhanced errors.", is_local=true, line=238, name="uninstall", params={}, returns={}, signature="()"}}, internal=true, module_doc=" Enhanced require with helpful error messages.\n Intercepts module-not-found errors and suggests similar modules.", records={{fields={{"install", "function()", ""}, {"uninstall", "function()", ""}, {"module_exists", "function(name: string): boolean", ""}, {"format_error", "function(name: string): string", ""}}, line=242, name="RequireModule"}}}, ["cosmic.sandbox"]={examples={{body="\n  local spawn = require(\"cosmic.child\")\n  local cosmic = arg[-1]\n  local script = [[\nlocal sandbox = require(\"cosmic.sandbox\")\nlocal avail = sandbox.available()\nif avail.fs and avail.sys then\n  assert(sandbox.apply({\n    fs = { ro = { \"/tmp\" } },\n    sys = { promises = \"stdio rpath\" },\n  }))\nelse\n  local ok, err = sandbox.apply({\n    fs = { ro = { \"/tmp\" } },\n    sys = { promises = \"stdio rpath\" },\n  })\n  assert(not ok and err:find(\"unsupported\"))\nend\nio.write(\"done\\n\")\n]]\n  local r = spawn.run({cosmic, \"-e\", script}) as spawn.Result\n  io.write(r.stdout)\n  -- Output:\n  -- done\n", description=" Example_apply sandboxes a subprocess to a read-only view of /tmp and\n the stdio+rpath promise groups in one call. The facade is\n fail-closed: where a section cannot be enforced (no landlock, not\n OpenBSD), apply reports failure instead of pretending to restrict.", expected_output="done\n", line=9, name="Example_apply"}}, file="lib/cosmic/sandbox.tl", functions={{description=" True when this host can enforce an fs section: landlock on Linux,\n unveil natively on OpenBSD. (On Linux the libc backs unveil with\n landlock too; the facade uses cosmic.landlock directly there.)", is_local=true, line=93, name="fs_available", params={}, returns={}, signature="(): boolean"}, {description=" Report what this host can enforce. Sections requested in `apply`\n beyond this fail closed (or are skipped under `best_effort`).", is_local=true, line=105, name="available", params={}, returns={{description="per-section enforceability", return_type="Availability"}}, signature="(): Availability"}, {is_local=true, line=116, name="add_rules", params={}, returns={}, signature="(\n    out: {Rule},\n    seen: {string: integer},\n    paths: {string},\n    mask: integer\n  )"}, {description=" Translate an fs policy to `cosmic.landlock.restrict` options. Pure:\n no syscalls, no side effects — exported so the mapping is\n inspectable and unit-testable. `no_new_privs` is set so landlock\n applies without CAP_SYS_ADMIN. An empty or nil policy produces an\n empty rules list, which denies everything when applied.", is_local=true, line=142, name="plan_landlock", params={{description="nil treated as empty (deny-all)", name="fs", param_type="Fs"}}, returns={{description="options for cosmic.landlock.restrict", return_type="RestrictOptions"}}, signature="(fs: Fs): RestrictOptions"}, {is_local=true, line=157, name="apply_fs_unveil", params={}, returns={}, signature="(fs: Fs): boolean, string"}, {is_local=true, line=172, name="apply_fs", params={}, returns={}, signature="(fs: Fs): boolean, string"}, {is_local=true, line=181, name="check_promises", params={}, returns={}, signature="(promises: string, label: string): string"}, {is_local=true, line=194, name="check_policy", params={}, returns={}, signature="(policy: Policy): string"}, {description=" Apply a sandbox policy to the current process. Irreversible.\n The policy is validated and this host's enforceability checked for\n every requested section *before* anything is applied, so a failure\n return means nothing changed. Sections then apply in enforced\n order: `fs` first (landlock on Linux, unveil on OpenBSD), `sys`\n (pledge) second — the reverse would let the pledge filter block the\n filesystem-sandbox syscalls.\n Fail-closed: a requested section this host cannot enforce returns\n `false, \"sandbox: ... unsupported on this host\"`. With\n `best_effort = true` unenforceable sections are skipped instead and\n apply reports success for the sections that did enforce.", is_local=true, line=244, name="apply", params={{description="fs and/or sys sections, best_effort flag", name="policy", param_type="Policy"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message on failure", return_type="string?"}}, signature="(policy: Policy): boolean, string"}}, module_doc=" One-call, fail-closed sandbox facade over unveil, landlock, and\n pledge.\n\n cosmic ships three mechanism-level sandbox modules with overlapping\n stories: `cosmic.landlock` (Linux), `cosmic.unveil` (OpenBSD, or\n Linux where the libc backs it with landlock), and `cosmic.pledge`\n (Linux, OpenBSD). This module is the one to reach for unless you\n need mechanism-specific control: it takes a single declarative\n policy, picks the right mechanism per OS, and applies the sections\n in the only order that works (fs before sys — a pledged process may\n no longer be allowed to install a filesystem sandbox).\n\n     local sandbox = require(\"cosmic.sandbox\")\n     assert(sandbox.apply{\n       fs = { ro = { \"/usr\" }, rw = { \"/tmp\" } },\n       sys = { promises = \"stdio rpath wpath\" },\n     })\n\n Like the mechanism modules, the facade is fail-closed: a section\n that cannot be enforced on this host makes `apply` return\n `false, \"sandbox: ... unsupported on this host\"` before anything is\n applied, unless `best_effort = true` opts into skipping unenforceable\n sections. `available()` reports what this host can enforce.\n\n Applying is irreversible and process-wide; policies can only be\n narrowed by further calls. `cosmic.quicksand.Box` consumes the same\n `fs` schema for its boxed workloads.", records={{description=" Filesystem policy: path allowlists. Everything not listed is denied\n once the policy applies. `ro` paths are readable *and executable*\n (so binaries under read-only roots can run); `rw` paths are\n readable and writable, including creating and removing entries, but\n never executable; `exec` is an alias of `ro` that documents intent.\n A path listed in several groups gets the union of their access.", fields={{"ro", "{string}", ""}, {"rw", "{string}", ""}, {"exec", "{string}", ""}}, line=39, name="Fs"}, {description=" System-call policy: pledge promise groups as a space-separated\n string (see cosmic.pledge for the group list; the `Promise` enum\n there names every valid token). `exec` optionally sets the promises\n children keep after execve.", fields={{"promises", "string", ""}, {"exec", "string", ""}}, line=49, name="Sys"}, {description=" A full sandbox policy. Each section is optional but at least one\n must be present. `best_effort = true` skips sections this host\n cannot enforce instead of failing closed.", fields={{"fs", "Fs", ""}, {"sys", "Sys", ""}, {"best_effort", "boolean", ""}}, line=57, name="Policy"}, {description=" What this host can enforce: `fs` (landlock on Linux, unveil on\n OpenBSD) and `sys` (pledge).", fields={{"fs", "boolean", ""}, {"sys", "boolean", ""}}, line=65, name="Availability"}, {fields={{"apply", "function(policy: Policy): boolean, string", ""}, {"available", "function(): Availability", ""}, {"plan_landlock", "function(fs: Fs): RestrictOptions", ""}}, line=73, name="SandboxModule"}}}, ["cosmic.shm"]={examples={}, file="lib/cosmic/shm.tl", functions={{description=" Validate a 0-based word index against the region size.", is_local=true, line=59, name="check_word", params={}, returns={}, signature="(word_index: number, size: number, op: string): string"}, {description=" Translate a pcall failure (a residual binding throw) into the\n error-return convention.", is_local=true, line=69, name="thrown", params={}, returns={}, signature="(op: string, err: any): string"}, {description=" Wrap the raw unix.Memory userdata in a Memory record whose methods\n validate bounds in Lua and return nil, err instead of throwing.", is_local=true, line=75, name="wrap", params={}, returns={}, signature="(raw: unix.Memory, size: number): Memory"}, {is_local=true, line=140, name="atomic", params={}, returns={}, signature="(op: string, fn: any, word_index: number, value: number): number | nil, string"}, {description=" Creates a shared memory region.\n The memory is shared across fork() and can be used for inter-process\n communication with atomic operations and futex synchronization.\n Example usage for a simple mutex:\n ```lua\n local shm = require(\"cosmic.shm\")\n local mem = assert(shm.mapshared(8000 * 8))\n local LOCK = 0  -- word index for lock\n -- Lock acquisition\n while mem:xchg(LOCK, 1) == 1 do\n   mem:wait(LOCK, 1)\n end\n -- Critical section here\n -- Unlock\n mem:store(LOCK, 0)\n mem:wake(LOCK, 1)\n ```", is_local=true, line=241, name="mapshared", params={{description="Size in bytes: positive, a multiple of the 8-byte word size", name="size", param_type="number"}}, returns={{description="| nil Shared memory object, or nil on failure", return_type="Memory"}, {description="Error message on failure", return_type="string?"}}, signature="(size: number): Memory | nil, string"}, {is_local=false, line=78, name="mem:size", params={}, returns={}, signature="(): number"}, {is_local=false, line=82, name="mem:read", params={}, returns={}, signature="(offset?: number, bytes?: number): string | nil, string"}, {is_local=false, line=98, name="mem:write", params={}, returns={}, signature="(data: string, offset?: number, bytes?: number): boolean, string"}, {is_local=false, line=115, name="mem:load", params={}, returns={}, signature="(word_index: number): number | nil, string"}, {is_local=false, line=127, name="mem:store", params={}, returns={}, signature="(word_index: number, value: number): boolean, string"}, {is_local=false, line=153, name="mem:xchg", params={}, returns={}, signature="(word_index: number, value: number): number | nil, string"}, {is_local=false, line=157, name="mem:fetch_add", params={}, returns={}, signature="(word_index: number, value: number): number | nil, string"}, {is_local=false, line=161, name="mem:fetch_and", params={}, returns={}, signature="(word_index: number, value: number): number | nil, string"}, {is_local=false, line=165, name="mem:fetch_or", params={}, returns={}, signature="(word_index: number, value: number): number | nil, string"}, {is_local=false, line=169, name="mem:fetch_xor", params={}, returns={}, signature="(word_index: number, value: number): number | nil, string"}, {is_local=false, line=173, name="mem:cmpxchg", params={}, returns={}, signature="(word_index: number, old: number, new: number): boolean | nil, number, string"}, {is_local=false, line=185, name="mem:wait", params={}, returns={}, signature="(word_index: number, expect: number, abs_deadline?: number, nanos?: number): number | nil, string"}, {is_local=false, line=203, name="mem:wake", params={}, returns={}, signature="(word_index: number, count?: number): number"}}, module_doc=" Shared memory for inter-process communication.\n Provides atomic operations and wait/wake primitives for synchronization.\n Memory created with mapshared is shared across fork() and provides\n fundamental synchronization primitives including futexes.\n\n This is a real wrapper over unix.mapshared, not a passthrough: sizes\n and offsets are validated in Lua (the region size is known at\n mapshared time) so failures return nil, err per the stdlib error\n convention instead of throwing, and residual binding throws are\n pcall-translated.", records={{description=" Shared memory region with atomic word operations and futexes.\n Words are 64-bit; word_index is 0-based. Futex words (wait/wake)\n only inspect the low 32 bits — store only int32 values in words\n you wait on.", fields={{"read", "function(self: Memory, offset?: number, bytes?: number): string | nil, string", " Read bytes from the region. With no bytes count, reads up to the\n first NUL byte (string semantics)."}, {"write", "function(self: Memory, data: string, offset?: number, bytes?: number): boolean, string", " Write bytes to the region (appends a NUL when no count is given)."}, {"load", "function(self: Memory, word_index: number): number | nil, string", " Atomic load of a word."}, {"store", "function(self: Memory, word_index: number, value: number): boolean, string", " Atomic store to a word."}, {"xchg", "function(self: Memory, word_index: number, value: number): number | nil, string", " Atomic exchange; returns the old value."}, {"cmpxchg", "function(self: Memory, word_index: number, old: number, new: number): boolean | nil, number, string", " Compare-and-exchange; returns success plus the actual old value."}, {"fetch_add", "function(self: Memory, word_index: number, value: number): number | nil, string", " Atomic add; returns the old value."}, {"fetch_and", "function(self: Memory, word_index: number, value: number): number | nil, string", " Atomic AND; returns the old value."}, {"fetch_or", "function(self: Memory, word_index: number, value: number): number | nil, string", " Atomic OR; returns the old value."}, {"fetch_xor", "function(self: Memory, word_index: number, value: number): number | nil, string", " Atomic XOR; returns the old value."}, {"wait", "function(self: Memory, word_index: number, expect: number, abs_deadline?: number, nanos?: number): number | nil, string", " Wait until the word no longer holds `expect`. Returns 0 when\n woken; nil plus an error naming EAGAIN (value already differed),\n ETIMEDOUT (deadline expired), or EINTR (signal)."}, {"wake", "function(self: Memory, word_index: number, count?: number): number", " Wake processes waiting on a word; returns how many woke."}, {"size", "function(self: Memory): number", " The mapped region size in bytes."}}, line=17, name="Memory"}, {description=" Module type for shared memory operations.", fields={{"mapshared", "function(size: number): Memory | nil, string", ""}}, line=17, name="ShmModule"}}}, ["cosmic.signal"]={examples={}, file="lib/cosmic/signal.tl", functions={{description=" Send a signal to a process.", is_local=true, line=142, name="kill", params={{description="The process ID (>0 for specific process, 0 for process group, -1 for all)", name="pid", param_type="number"}, {description="The signal to send", name="sig", param_type="number"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message on failure", return_type="string?"}}, signature="(pid: number, sig: number): boolean, string"}, {description=" Send a signal to a process group.", is_local=true, line=155, name="killpg", params={{description="The process group ID", name="pgrp", param_type="number"}, {description="The signal to send", name="sig", param_type="number"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message on failure", return_type="string?"}}, signature="(pgrp: number, sig: number): boolean, string"}, {description=" Send a signal to the current process.\n Equivalent to kill(getpid(), sig).", is_local=true, line=168, name="raise", params={{description="The signal to send", name="sig", param_type="number"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message on failure", return_type="string?"}}, signature="(sig: number): boolean, string"}, {description=" 