which", "number", ""}, {"valuesec", "number", ""}, {"valuens", "number", ""}, {"intervalsec", "number", ""}, {"intervalns", "number", ""}}, line=7, name="SetitimerOptions"}, {description=" Result from setitimer: previous timer values.", fields={{"valuesec", "number", ""}, {"valuens", "number", ""}, {"intervalsec", "number", ""}, {"intervalns", "number", ""}}, line=16, name="SetitimerResult"}, {description=" Signal set for blocking, unblocking, and waiting on signals.\n Wraps unix.Sigset for use with sigprocmask, sigaction, and sigsuspend.\n Sigset is PascalCase because it is a record constructor: cosmic names\n functions snake_case and reserves PascalCase for records and the\n functions that construct them.", fields={{"add", "function(self: Sigset, sig: number)", " Adds signal to bitset."}, {"remove", "function(self: Sigset, sig: number)", " Removes signal from bitset."}, {"fill", "function(self: Sigset)", " Sets all bits in signal bitset to true."}, {"clear", "function(self: Sigset)", " Sets all bits in signal bitset to false."}, {"contains", "function(self: Sigset, sig: number): boolean", " Returns true if signal is in the bitset."}}, line=28, name="Sigset"}, {description=" Signal handling module.\n Provides signal constants, sigaction, sigprocmask, sigsuspend, and delivery functions.", fields={{"SIGABRT", "number", ""}, {"SIGALRM", "number", ""}, {"SIGBUS", "number", ""}, {"SIGCHLD", "number", ""}, {"SIGCONT", "number", ""}, {"SIGFPE", "number", ""}, {"SIGHUP", "number", ""}, {"SIGILL", "number", ""}, {"SIGINT", "number", ""}, {"SIGKILL", "number", ""}, {"SIGPIPE", "number", ""}, {"SIGPROF", "number", ""}, {"SIGQUIT", "number", ""}, {"SIGSEGV", "number", ""}, {"SIGSTOP", "number", ""}, {"SIGSYS", "number", ""}, {"SIGTERM", "number", ""}, {"SIGTRAP", "number", ""}, {"SIGTSTP", "number", ""}, {"SIGTTIN", "number", ""}, {"SIGTTOU", "number", ""}, {"SIGURG", "number", ""}, {"SIGUSR1", "number", ""}, {"SIGUSR2", "number", ""}, {"SIGVTALRM", "number", ""}, {"SIGWINCH",