l."}, {"killpg", "function(pgrp: number, sig: number): boolean, string", " Send a signal to a process group."}, {"raise", "function(sig: number): boolean, string", " Send a signal to the current process."}, {"strsignal", "function(sig: number): string", " Get the name of a signal."}, {"pid", "number, sig: number): boolean, string", " Send a signal to a process."}}, line=43, name="SignalModule"}}}, ["cosmic.sqlite"]={examples={{body="\n  local sqlite = require(\"cosmic.sqlite\")\n  local fs = require(\"cosmic.fs\")\n\n  -- Relative paths resolve against cwd\n  local tmpdir = os.getenv(\"TEST_TMPDIR\") or \"/tmp\"\n  local dbpath = fs.join(tmpdir, \"example.db\")\n  local db = sqlite.open(dbpath) as sqlite.Database\n  db:exec(\"CREATE TABLE t (x TEXT)\")\n  db:exec(\"INSERT INTO t (x) VALUES ('hello')\")\n  local row = db:query_one(\"SELECT x FROM t\") as {string: any}\n  print(row.x)\n  db:close()\n  os.remove(dbpath)\n\n  -- Absolute paths work as expected:\n  --   local db = sqlite.open(\"/var/data/app.db\")\n  -- In-memory databases are not written to disk:\n  --   local db = sqlite.open(\":memory:\")\n  -- Output:\n  -- hello\n", description=" Example_open_file demonstrates database file path resolution", expected_output="hello\n", line=12, name="Example_open_file"}, {body="\n  local sqlite = require(\"cosmic.sqlite\")\n  local db = sqlite.open(\":memory:\") as sqlite.Database\n  db:exec(\"CREATE TABLE kv (k TEXT PRIMARY KEY, v TEXT)\")\n  db:exec(\"INSERT INTO kv (k, v) VALUES ('hello', 'world')\")\n  for row in db:query(\"SELECT * FROM kv\") as Rows do\n    print(row.k, row.v)\n  end\n  db:close()\n  -- Output:\n  -- hello\tworld\n", description=" Example_open demonstrates opening an in-memory database", expected_output="hello\tworld\n", line=36, name="Example_open"}, {body="\n  local sqlite = require(\"cosmic.sqlite\")\n  local db = sqlite.open(\":memory:\") as sqlite.Database\n  db:exec(\"CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT)\")\n\n  local stmt = db:prepare(\"INSERT INTO users (name) VALUES (?)\") as sqlite.Statement\n  stmt:bind(\"Alice\")\n  stmt:exec()\n  stmt:reset()\n  stmt:bind(\"Bob\")\n  stmt:exec()\n  stmt:close()\n\n  for row in db:query(\"SELECT * FROM users ORDER BY id\") as Rows do\n    print(row.id, row.name)\n  end\n  db:close()\n  -- Output:\n  -- 1\tAlice\n  -- 2\tBob\n", description=" Example_prepared demonstrates prepared statements", expected_output="1\tAlice\n  -- 2\tBob\n", line=50, name="Example_prepared"}, {body="\n  local sqlite = require(\"cosmic.sqlite\")\n  local db = sqlite.open(\":memory:\") as sqlite.Database\n  db:exec(\"CREATE TABLE nums (n INTEGER)\")\n  for i = 1, 5 do\n    db:exec(\"INSERT INTO nums (n) VALUES (\" .. i .. \")\")\n  end\n\n  for row in db:query(\"SELECT * FROM nums WHERE n > ?\", 2) as Rows do\n    print(row.n)\n  end\n  db:close()\n  -- Output:\n  -- 3\n  -- 4\n  -- 5\n", description=" Example_query_params demonstrates query with parameters", expected_output="3\n  -- 4\n  -- 5\n", line=73, name="Example_query_params"}, {body="\n  local sqlite = require(\"cosmic.sqlite\")\n  local db = sqlite.open(\":memory:\") as sqlite.Database\n  db:exec(\"CREATE TABLE cities (id INTEGER PRIMARY KEY, name TEXT, pop INTEGER)\")\n\n  db:exec(\"INSERT INTO cities (name, pop) VALUES (?, ?)\", \"Tokyo\", 13960000)\n  db:exec(\"INSERT INTO cities (name, pop) VALUES (?, ?)\", \"Delhi\", 16787941)\n  db:exec(\"INSERT INTO cities (name, pop) VALUES (?, ?)\", \"Shanghai\", 24870895)\n\n  for row in db:query(\"SELECT * FROM cities ORDER BY pop DESC\") as Rows do\n    print(row.name, row.pop)\n  end\n  db:close()\n  -- Output:\n  -- Shanghai\t24870895\n  -- Delhi\t16787941\n  -- Tokyo\t13960000\n", description=" Example_exec_params demonstrates exec with parameter binding", expected_output="Shanghai\t24870895\n  -- Delhi\t16787941\n  -- Tokyo\t13960000\n", line=92, name="Example_exec_params"}, {body="\n  local sqlite = require(\"cosmic.sqlite\")\n  local db = sqlite.open(\":memory:\") as sqlite.Database\n  db:exec(\"CREATE TABLE files (path TEXT)\")\n  db:exec(\"INSERT INTO files (path) VALUES (?)\", \"src/main.tl\")\n  db:exec(\"INSERT INTO files (path) VALUES (?)\", \"src/util.tl\")\n  db:exec(\"INSERT INTO files (path) VALUES (?)\", \"docs/readme.md\")\n\n  for row in db:query(\"SELECT path FROM files WHERE path LIKE ?\", \"%src%\") as Rows do\n    print(row.path)\n  end\n  db:close()\n  -- Output:\n  -- src/main.tl\n  -- src/util.tl\n", description=" Example_query_like demonstrates substring matching with LIKE\n (the SQL wildcard is %, not *)", expected_output="src/main.tl\n  -- src/util.tl\n", line=113, name="Example_query_like"}}, file="lib/cosmic/sqlite/init.tl", functions={{is_local=true, line=108, name="make_statement", params={}, returns={}, signature="(raw_stmt: RawStatement, raw_db: RawDatabase): Statement"}, {is_local=true, line=0x0100, name="make_database", params={}, returns={}, signature="(raw_db: RawDatabase): Database"}, {description=" Open or create an SQLite database.\n Relative paths are resolved against the current working directory.\n Absolute paths (e.g. \"/var/data/app.db\") work as expected.\n Use \":memory:\" for an in-memory database that is not written to disk.\n The file is created if it does not already exist (unless read_only).\n A 5000ms busy timeout is set by default so two processes sharing a\n file database wait for each other instead of failing instantly with\n SQLITE_BUSY; override with opts.busy_timeout_ms.", is_local=true, line=420, name="open", params={{description="Database path (use \":memory:\" for in-memory)", name="filename", param_type="string"}, {description="busy_timeout_ms and read_only", name="opts", param_type="OpenOptions?"}}, returns={{description="| nil Database handle with __close support", return_type="Database"}, {description="Error message on failure", return_type="string"}}, signature="(filename: string, opts?: OpenOptions): Database | nil, string"}, {description=" Bind parameter