ction(): boolean", ""}, {"stdout_isatty", "function(): boolean", ""}, {"stderr_isatty", "function(): boolean", ""}, {"getattr", "function(fd: number): Termios | nil, string", ""}, {"setattr", "function(fd: number, action: number, termios: Termios): boolean, string", ""}, {"make_raw", "function(termios: Termios, opts?: RawOptions): Termios", ""}, {"raw", "function(fd: number, opts?: RawOptions): Termios | nil, string", ""}, {"noecho", "function(fd: number): Termios | nil, string", ""}, {"restore", "function(fd: number, termios: Termios): boolean, string", ""}, {"getpass", "function(prompt: string): string | nil, string", ""}}, line=10, name="TtyModule"}}}, ["cosmic.unveil"]={examples={{body="\n  local spawn = require(\"cosmic.child\")\n  local cosmic = arg[-1]\n  local script = [[\nlocal unveil = require(\"cosmic.unveil\")\nif unveil.available() then\n  assert(unveil.allow(\"/tmp\", \"r\"))\n  assert(unveil.commit())\nelse\n  local ok, err = unveil.allow(\"/tmp\", \"r\")\n  assert(not ok and err:find(\"unsupported\"))\nend\nio.write(\"done\\n\")\n]]\n  local r = spawn.run({cosmic, \"-e\", script}) as spawn.Result\n  io.write(r.stdout)\n  -- Output:\n  -- done\n", description=" Example_allow demonstrates unveiling a single directory read-only and\n committing the policy. The API is fail-closed: on hosts without a\n backing sandbox, allow() returns false + \"unveil unsupported on this\n host\" instead of pretending to restrict.", expected_output="done\n", line=11, name="Example_allow"}}, file="lib/cosmic/unveil.tl", functions={{description=" True when unveil is actually enforceable on this host: OpenBSD, or\n Linux with Landlock ABI >= 1. Derived, never probed with unveil\n itself — `unix.unveil(nil, nil)` is the commit call, so probing it\n would lock this very process into a deny-all sandbox. The libc backs\n unveil with Landlock on Linux, so it enforces exactly when Landlock\n does; everywhere else the raw call deliberately fails open, which is\n precisely what this wrapper refuses to pass through. Cached.", is_local=true, line=69, name="available", params={}, returns={{description="True when unveil can be enforced", return_type="boolean"}}, signature="(): boolean"}, {description=" Unveil a path with the given permission set.\n Fail-closed: on a host where unveil cannot be enforced this returns\n `false, \"unveil unsupported on this host\"` rather than succeeding\n without a sandbox; pass `best_effort = true` to treat that case as a\n successful no-op.", is_local=true, line=96, name="allow", params={{description="Path to unveil", name="path", param_type="string"}, {description="Permission string like \"r\", \"rw\", \"rwxc\"", name="permissions", param_type="string"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message on failure", return_type="string?"}}, signature="(path: string, permissions: Perm, opts?: UnveilOptions): boolean, string"}, {description=" Commit the unveil policy: the allowlist becomes final and further\n unveil calls are rejected. Fail-closed like `allow`.", is_local=true, line=113, name="commit", params={}, returns={{description="True on success", return_type="boolean"}, {description="Error message on failure", return_type="string?"}}, signature="(opts?: UnveilOptions): boolean, string"}, {description=" DEPRECATED compatibility shim for the pre-stable API: delegates to\n `allow(path, permissions)`, or to `commit()` when both arguments are\n nil (the old commit spelling). New code should call allow/commit.", is_local=true, line=133, name="apply", params={{description="Path to unveil (nil to commit)", name="path", param_type="string|nil"}, {description="Permission string (nil to commit)", name="permissions", param_type="string|nil"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message on failure", return_type="string?"}}, signature="(path: string, permissions: string): boolean, string"}}, module_doc=" Restrict filesystem visibility to an allowlisted set of paths.\n\n Once a process unveils any path, the entire filesystem is hidden\n except for the paths that have been unveiled. Paths are revealed one\n at a time with `allow(path, permissions)`; when done, `commit()`\n seals the policy and further unveil calls become no-ops or errors.\n\n The API is fail-closed: unveil is enforceable on OpenBSD (natively)\n and on Linux kernels with Landlock (the libc's backing mechanism).\n Anywhere else `allow`/`commit` return `false, \"unveil unsupported on\n this host\"` instead of reporting a sandbox that does not exist.\n Callers that prefer the old fail-open behavior opt in explicitly\n with `best_effort = true`, or branch on `available()` themselves.\n\n Unveil pairs naturally with `cosmic.pledge`: pledge narrows which\n system calls are allowed; unveil narrows which files those calls can\n touch.\n\n Permissions (strings, combinable):\n\n   r  read-only path operations (matches pledge \"rpath\")\n   w  write operations           (matches pledge \"wpath\")\n   x  execute operations         (matches pledge \"exec\" / \"execnative\")\n   c  create and remove paths    (matches pledge \"cpath\")", records={{description=" Options for `allow` / `commit`. `best_effort` turns an unsupported\n host into a successful no-op instead of an error — the explicit\n fail-open escape hatch.", fields={{"best_effort", "boolean", ""}}, line=54, name="UnveilOptions"}, {fields={{"allow", "function(path: string, permissions: Perm, opts?: UnveilOptions): boolean, string", ""}, {"commit", "function(opts?: UnveilOptions): boolean, string", ""}, {"available", "function(): boolean", ""}, {"apply", "function(path: string, permissions: string): boolean, string", ""}}, line=140, name="UnveilModule"}}}, ["cosmic.url"]={examples={}, file="lib/cosmic/url.tl", functions={{description=" Percent-encode a string for use as a URL query parameter value.\n Use this when building query strings manually: `\"q=\" .. url.encode(search_term)`.\n Spaces become %20, special characters become %XX hex sequences.\n For other URL components, use the specific escape functions:\n - `escape_path()`: encode a URL path (preserves slashes)\n - `escape_segment()`: encode a single path segment (escapes slashes)\n - `escape_host()`: encode a hostname\n - `escape_fragment()`: encode a URL fragment", is_local=true, line=16, name="encode", params={{description="The string to encode", name="str", param_type="string"}}, returns={{description="The percent-encoded string", return_type="string"}}, signature="(str: string): string"}, {description=" Decode a percent-encoded string.\n Handles %XX sequences and + as space.", is_local=true, line=25, name="decode", params={{description="The percent-encoded string", name="str", param_type="string"}}, returns={{description="| nil The decoded string, or nil on error", return_type="string"}, {description="Error message if decoding failed", return_type="string?"}}, signature="(str: string): string | nil, string"}, {description=" Parse a query string into its key-value pairs, keeping every value.\n Keys and values are percent-decoded; a repeated key's values arrive\n in order. A flag-style key with no `=` yields one empty-string value.", is_local=true, line=43, name="parse_query", params={{description="The query string (without leading ?)", name="query", param_type="string"}}, returns={{description="Decoded keys, each with all its values in order", return_type="{string:{string}}"}}, signature="(query: string): {string: {string}}"}, {description=" Parse a URL into its components.\n The query field is re-encoded so delimiters inside values survive\n (e.g. `?a=x%26y` stays one parameter); decode it with `parse_query`.", is_local=true, line=76, name="parse", params={{description="The URL to parse", name="url", param_type="string"}}, returns={{description="| nil The parsed URL components, or nil on error", return_type="Url"}, {description="Error message if parsing failed", return_type="string?"}}, signature="(url: string): Url | nil, string"}, {description=" Format a Url back into a string — the inverse of `parse`.\n Each component is escaped for its position, so a parse/format round\n trip yields an equivalent URL.", is_local=true, line=127, name="format", params={{description="The URL components to format", name="u", param_type="Url"}}, returns={{description="The formatted URL", return_type="string"}}, signature="(u: Url): string"}, {description=" Parse a host:port string into its components.\n IPv6 hosts must be bracketed (\"[::1]\" or \"[::1]:8080\"); a port, when\n present, must be an integer in 1..65535.", is_local=true, line=151, name="parse_host", params={{description="The host:port string (e.g., \"example.com:8080\")", name="hostport", param_type="string"}}, returns={{description="| nil The host, or nil on error", return_type="string"}, {description="The port, or nil if not specified", return_type="integer?"}, {description="Error message if parsing failed", return_type="string?"}}, signature="(hostport: string): string | nil, integer, string"}, {description=" Escape a hostname for use in a URL.\n Handles internationalized domain names and special characters.", is_local=true, line=202, name="escape_host", params={{description="The hostname to escape", name="str", param_type="string"}}, returns={{description="The escaped hostname", return_type="string"}}, signature="(str: string): string"}, {description=" Escape a URL path, preserving forward slashes.\n Use for paths like `/users/john doe` -> `/users/john%20doe`.\n To escape a single segment (including slashes), use `escape_segment()`.", is_local=true, line=211, name="escape_path", params={{description="The path to escape", name="str", param_type="string"}}, returns={{description="The escaped path", return_type="string"}}, signature="(str: string): string"}, {description=" Escape a single URL path segment, including forward slashes.\n Use when the segment itself may contain slashes: `file/name.txt`