ling process.\n On Windows this is polyfilled as getuid().", is_local=true, line=31, name="getegid", params={}, returns={{description="The effective group ID", return_type="number"}}, signature="(): number"}, {description=" Get the login name of the user running the process.", is_local=true, line=38, name="getlogin", params={}, returns={{description="| nil The login name, or nil on failure", return_type="string"}, {description="Error message if the login name cannot be determined", return_type="string?"}}, signature="(): string | nil, string"}, {description=" Set the user ID of the calling process.\n Returns ENOSYS on Windows NT if uid isn't getuid().", is_local=true, line=51, name="setuid", params={{description="The user ID to set", name="uid", param_type="number"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message on failure", return_type="string?"}}, signature="(uid: number): boolean, string"}, {description=" Set the group ID of the calling process.\n Returns ENOSYS on Windows NT if gid isn't getgid().", is_local=true, line=64, name="setgid", params={{description="The group ID to set", name="gid", param_type="number"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message on failure", return_type="string?"}}, signature="(gid: number): boolean, string"}, {description=" Set the filesystem user ID.", is_local=true, line=76, name="setfsuid", params={{description="The filesystem user ID to set", name="uid", param_type="number"}}, returns={{description="True on success", return_type="boolean"}, {description="Error message on failure", return_type="string?"}}, signature="(uid: number): boolean, string"}, {description=" Set real, effective, and saved user IDs.\n Pass -1 for any argument to leave that ID unchanged.", is_local=true, line=91, name="setresuid", params={{description="The real user ID to set (-1 to leave unchanged)", name="real", param_type="number"}, {description="The effectiv