ns={{is_local=true, line=112, name="raw_options", params={}, returns={}, signature="(options: OpenOptions): {string: number}"}, {description=" Open a ZIP archive for reading.", is_local=true, line=124, name="reader", params={{description="File path or file descriptor", name="path", param_type="string|number"}, {description="Size limits", name="options", param_type="OpenOptions?"}}, returns={{description="| nil The archive reader, or nil on error", return_type="Reader"}, {description="Error message if opening failed", return_type="string?"}}, signature="(path: string | number, options?: OpenOptions): Reader | nil, string"}, {description=" Create a new ZIP archive for writing. Any existing file is truncated.", is_local=true, line=143, name="writer", params={{description="File path or file descriptor", name="path", param_type="string|number"}, {description="Compression level and size limits", name="options", param_type="OpenOptions?"}}, returns={{description="| nil The archive writer, or nil on error", return_type="Writer"}, {description="Error message if opening failed", return_type="string?"}}, signature="(path: string | number, options?: OpenOptions): Writer | nil, string"}, {description=" Open a ZIP archive for appending, creating it if it does not exist.\n Unlike reader/writer, a file descriptor is not accepted; the archive\n must be given as a path.", is_local=true, line=164, name="appender", params={{description="File path", name="path", param_type="string"}, {description="Compression level and size limits", name="options", param_type="OpenOptions?"}}, returns={{description="| nil The archive appender, or nil on error", return_type="Appender"}, {description="Error message if opening failed", return_type="string?"}}, signature="(path: string, options?: OpenOptions): Appender | nil, string"}, {description=" Open a ZIP archive from in-memory data for reading.", is_local=true, line=183, name="from", params={{description="The ZIP archive data", name="data", param_type="string"}, {description="Size limits", name="options", param_type="OpenOptions?"}}, returns={{description="The archive reader, or nil on error", return_type="Reader?"}, {description="Error message if opening failed", return_type="string?"}}, signature="(data: string, options?: OpenOptions): Reader | nil, string"}, {description=" Report whether a zip entry name would escape the extraction root\n (zip-slip). Rejects absolute paths — POSIX (`/x`), Windows/UNC\n (`\\x`, `\\\\server\\share`), and drive-letter (`C:\\x`, `C:/x`, `C:x`) —\n and any `..` traversal component. Both `/` and `\\` are treated as\n separators, since cosmic executables also run on Windows where a\n `..\\evil` entry would otherwise slip past a POSIX-only guard.", is_local=true, line=203, name="unsafe_entry", params={}, returns={}, signature="(name: string): boolean"}, {description=" Extract every entry of an open reader into destdir, refusing archives\n that attempt zip-slip. All entry names (and sizes, when\n opts.max_file_size is set) are validated before anything is written, so\n a malicious archive fails without leaving partial output. File modes\n are taken from the archive masked to 0777 (setuid/setgid/sticky bits\n are stripped); entries without a mode default to 0644. Existing files\n are overwritten. The reader is left open.", is_local=true, line=230, name="extract", params={{description="An open archive reader (from reader() or from())", name="r", param_type="Reader"}, {description="Directory to extract into (created if needed)", name="destdir", param_type="string"}, {description="Per-entry size limit", name="opts", param_type="ExtractOptions?"}}, returns={{description="true when every entry was written", return_type="boolean"}, {description="Error message if validation or writing failed", return_type="string?"}}, signature="(r: Reader, destdir: string, opts?: ExtractOptions): boolean, string"}, {is_local=true, line=248, name="ensure_dir", params={}, returns={}, signature="(dir: string): boolean, string"}}, module_doc=" ZIP archive reading and writing utilities.\n Wraps cosmo.zip with a convenient Teal-typed interface for creating,\n reading, and modifying ZIP archives. Use `reader`/`writer`/`appender`\n to open by path, `from` for in-memory data, and `extract` to safely\n unpack a reader to a directory (entry names from an archive are\n attacker-controlled; never write them to disk without `extract`'s\n zip-slip validation).", records={{description=" Options for opening a ZIP archive.", fields={{"level", "number", " Compression level 0-9 (0=none, 9=maximum). Used when writing/appending."}, {"max_file_size", "number", " Maximum file size limit in bytes."}}, line=12, name="OpenOptions"}, {description=" Options for adding a file to a ZIP archive.", fields={{"method", "string", " Compression method: \"store\" (no compression) or \"deflate\" (compressed)."}, {"mtime", "number", " Modification time as Unix timestamp."}, {"mode", "number", " Unix file mode/permissions (default 0644)."}}, line=20, name="AddOptions"}, {description=" File metadata within a ZIP archive.", fields={{"size", "number", " Uncompressed file size in bytes."}, {"compressed_size", "number", " Compressed file size in bytes."}, {"crc32", "number", " CRC32 checksum of uncompressed data."}, {"mtime", "number", " Modification time as Unix timestamp."}, {"method", "number", " Compression method (0=stored, 8=deflated)."}, {"mode", "number", " Unix file mode/permissions."}}, line=30, name="Stat"}, {description=" Reader for extracting files from a ZIP archive.", fields={{"list", "function(self: Reader): {string}", " Lists all files in the ZIP archive.\n Entry names come raw from the central directory: an archive built by\n another tool can contain absolute or \"../\" names. Validate before\n using a name as a filesystem path, or use extract()."}, {"stat", "function(self: Reader, name: string): Stat | nil", " Gets metadata for a specific file in the archive."}, {"read", "function(self: Reader, name: string): string | nil, string", " Reads the contents of a file from the archive."}, {"close", "function(self: Reader)", " Closes the ZIP reader and releases resources."}}, line=46, name="Reader"}, {description=" Writer for creating new ZIP archives.", fields={{"add", "function(self: Writer, name: string, content: string, options?: AddOptions): boolean | nil, string", " Adds a file to the ZIP archive."}, {"close", "function(self: Writer)", " Closes the ZIP archive and writes the central directory."}}, line=70, name="Writer"}, {description=" Appender for adding files to an existing ZIP archive.", fields={{"add", "function(self: Appender, name: string, content: string, options?: AddOptions): boolean | nil, string", " Adds a file to the ZIP archive."}, {"remove", "function(self: Appender, name: string): boolean | nil, string", " Removes a file from the ZIP archive by name."}, {"close", "function(self: Appender)", " Closes the ZIP archive and writes the updated central directory."}}, line=84, name="Appender"}, {description=" Options for extract().", fields={{"max_file_size", "number", " Refuse any entry whose declared uncompressed size exceeds this many\n bytes (checked before anything is read or written)."}}, line=104, name="ExtractOptions"}, {fields={{"reader", "function(path: string | number, options?: OpenOptions): Reader | nil, string", ""}, {"writer", "function(path: string | number, options?: OpenOptions): Writer | nil, string", ""}, {"appender", "function(path: string, options?: OpenOptions): Appender | nil, string", ""}, {"from", "function(data: string, options?: OpenOptions): Reader | nil, string", ""}, {"extract", "function(r: Reader, destdir: string, opts?: ExtractOptions): boolean, string", ""}}, line=295, name="ZipModule"}}}, ["cosmo.argon2"]={examples={}, file="lib/types/cosmo/argon2.d.tl", functions={{description=" Hashes password.\n This is consistent with the README of the reference implementation:\n     >: assert(argon2.hash_encoded(\"password\", \"somesalt\", {\n         variant = \"argon2i\",\n         hash_len = 24,\n         t_cost = 2,\n     }))\n `salt` is a nonce value used to hash the string. It is optional: when it is\n `nil` or omitted, 16 random bytes are generated with a CSPRNG.\n `config.m_cost` is the memory hardness in kibibytes, which defaults\n to 4096 (4 mibibytes). It's recommended that this be tuned upwards.\n `config.t_cost` is the number of iterations, which defaults to 3.\n `config.parallelism` is the parallelism factor, which defaults to 1.\n `config.hash_len` is the number of desired bytes in hash output,\n which defaults to 32.\n `config.variant` may be:\n - `\"argon2id\"` blend of other two methods [default]\n - `\"argon2i\"` maximize resistance to side-channel attacks\n - `\"argon2d\"` maximize resistance to gpu cracking attacks", is_local=false, line=0, name="hash_encoded", params={{name="pass", param_type="string"}, {name="salt", param_type="string"}, {name="config", param_type="Config"}}, returns={{return_type="string"}, {return_type="string | nil"}}, signature="(pass: string, salt?: string, config?: Config): string, string | nil"}, {description=" Verifies a password against an encoded hash, e.g.\n     >: argon2.verify(encoded, \"password\")\n     true\n Returns `true` when the password matches. A plain mismatch returns\n `false` (with no error). A malformed `encoded` string returns\n `false, err`.", is_local=false, line=0, name="verify", params={{name="encoded", param_type="string"}, {name="pass", param_type="string"}}, returns={{return_type="boolean"}, {return_type="string | nil"}}, signature="(encoded: string, pass: string): boolean, string | nil"}}, module_doc="Type declarations for the `argon2` module.", records={{fields={{"m_cost", "number", " the memory hardness in kibibytes, which defaults to 4096 (4 mibibytes). It's recommended that this be tuned upwards."}, {"t_cost", "number", " the number of iterations, which defaults to `3`."}, {"parallelism", "number", " the parallelism factor, which defaults to `1`."}, {"hash_len", "number", " the number of desired bytes in hash output, which defaults to 32."}, {"variant", "string", " the Argon2 variant: `\"argon2id\"` blend of other two methods [default], `\"argon2i\"` maximize resistance to side-channel attacks, or `\"argon2d\"` maximize resistance to gpu cracking attacks"}}, line=0, name="Config"}}}, ["cosmo.getopt"]={examples={}, file="lib/types/cosmo/getopt.d.tl", functions={{description=" Parse a command-line argument vector in one shot.\n The optstring uses standard getopt format:\n - A letter means that option takes no argument\n - A letter followed by : means it requires an argument\n - A letter followed by :: means it takes an optional argument\n The longopts table contains entries like {\"name\", \"has_arg\", \"short\"}:\n - name: the long option name (e.g., \"help\" for --help)\n - has_arg: \"none\", \"required\", or \"optional\"\n - short: the equivalent short option character (e.g., \"h\"), or nil\n The result separates four outcomes. `opts` lists the recognized options in\n order, each as a {opt, arg} pair. `args` holds the leftover positional\n arguments. `unknown` holds unrecognized options (always spelled with their\n dashes, e.g. \"-x\" or \"--nope\"). `missing` holds the options that required an\n argument but were given none (named without dashes, e.g. \"o\"); this is kept\n distinct from `unknown` via getopt's leading-`:` protocol.\n Example - Basic usage:\n     local r = getopt.parse(arg, \"hvo:\", {\n       {\"help\",    \"none\",     \"h\"},\n       {\"verbose\", \"none\",     \"v\"},\n       {\"output\",  \"required\", \"o\"},\n     })\n     for _, o in ipairs(r.opts) do\n       if o.opt == \"h\" then\n         print(\"Usage: ...\")\n       elseif o.opt == \"v\" then\n         verbose = true\n       elseif o.opt == \"o\" then\n         output = o.arg\n       end\n     end\n     -- r.args     -- non-option arguments\n     -- r.unknown  -- unrecognized options, with dashes\n     -- r.missing  -- options missing a required argument\n Example - Handling repeated options:\n     local r = getopt.parse(arg, \"e:\")\n     local excludes = {}\n     for _, o in ipairs(r.opts) do\n       if o.opt == \"e\" then\n         table.insert(excludes, o.arg)\n       end\n     end\n     -- Now excludes contains all -e values: {\"foo\", \"bar\", \"spam\"}", is_local=false, line=0, name="parse", params={{name="args", param_type="{string}"}, {name="optstring", param_type="string"}, {name="longopts", param_type="{table}"}}, returns={{return_type="Result"}, {return_type="string | nil"}}, signature="(args: {string}, optstring: string, longopts?: {table}): Result, string | nil"}}, module_doc="Type declarations for the `getopt` module.", records={{description=" A single recognized option and its argument (nil when the option takes\n none). For a long option that has a short equivalent, `opt` is that short\n letter; for a long-only option, `opt` is the long name.", fields={{"opt", "string", ""}, {"arg", "string", ""}}, line=0, name="Option"}, {description=" The outcome of a single `getopt.parse` call.", fields={{"opts", "{Option}", " Recognized options, in the order encountered"}, {"args", "{string}", " Non-option (positional) arguments"}, {"unknown", "{string}", " Unrecognized options, each including its dashes"}, {"missing", "{string}", " Options that required an argument but got none"}}, line=0, name="Result"}}}, ["cosmo.lsqlite3"]={examples={}, file="lib/types/cosmo/lsqlite3.d.tl", functions={{description=" Opens (or creates if it does not exist) an SQLite database with name filename\n and returns its handle as userdata (the returned object should be used for all\n further method calls in connection with this specific database, see Database\n methods). Example:\n     myDB = lsqlite3.open('MyDatabase.sqlite3')  -- open\n     -- do some database calls...\n     myDB:close()  -- close\n In case of an error, the function returns `nil`, an error code and an error message.\n Since `0.9.4`, there is a second optional `flags` argument to `lsqlite3.open`.\n See https://www.sqlite.org/c3ref/open.html for an explanation of these flags and options.\n     local db = lsqlite3.open('foo.db', lsqlite3.OPEN_READWRITE + lsqlite3.OPEN_CREATE + lsqlite3.OPEN_SHAREDCACHE)", is_local=false, line=0, name="open", params={{name="filename", param_type="string"}, {name="flags", param_type="number"}}, returns={{return_type="Database"}, {return_type="number | nil"}, {return_type="string | nil"}}, signature="(filename: string, flags?: number): Database, number | nil, string | nil"}, {description=" Opens an SQLite database in memory and returns its handle as userdata. In case\n of an error, the function returns `nil`, an error code and an error message.\n (In-memory databases are volatile as they are never stored on disk.)", is_local=false, line=0, name="open_memory", params={}, returns={{return_type="Database"}, {return_type="number | nil"}, {return_type="string | nil"}}, signature="(): Database, number | nil, string | nil"}, {is_local=false, line=0, name="lversion", params={}, returns={{return_type="string"}}, signature="(): string"}, {is_local=false, line=0, name="version", params={}, returns={{return_type="string"}}, signature="(): string"}, {description=" Sets global SQLite3 library configuration options.\n `option` may be one of:\n - `lsqlite3.CONFIG_SINGLETHREAD`, `lsqlite3.CONFIG_MULTITHREAD`, or\n   `lsqlite3.CONFIG_SERIALIZED`: selects the global threading mode.\n   Returns `lsqlite3.OK` on success, or `nil` plus a numerical error\n   code on failure.\n - `lsqlite3.CONFIG_LOG`: installs a Lua callback that is invoked as\n   `func(udata, errcode, message)` for every SQLite3 log event, or\n   removes the current callback when `func` is `nil`. Returns\n   `lsqlite3.OK` followed by the previously installed callback and its\n   user data.", is_local=false, line=0, name="config", params={{name="option", param_type="number"}, {name="func", param_type="function"}, {name="udata", param_type="any"}}, returns={{return_type="number"}, {return_type="function | nil"}, {return_type="any"}, {return_type="number | nil"}}, signature="(option: number, func?: function, udata?: any): number, function | nil, any, number | nil"}}, module_doc="Type declarations for the `lsqlite3` module.", records={{description=" A callback context is available as a parameter inside the callback functions\n `db:create_aggregate()` and `db:create_function()`. It can be used to get\n further information about the state of a query.", fields={{"get_aggregate_data", "function(self: Context): any", ""}, {"set_aggregate_data", "function(self: Context, udata: any)", " Set the user-definable data field for callback funtions to `udata`."}, {"result", "function(self: Context, res?: string | number)", " Sets the result of a callback function to `res`. The type of the result\n depends on the type of `res` and is either a number or a string or `nil`.\n All other values will raise an error message."}, {"result_blob", "function(self: Context, blob: string)", " Sets the result of a callback function to the binary string in blob."}, {"result_double", "function(self: Context, double: number)", " Sets the result of a callback function to the value number."}, {"result_number", "function(self: Context, double: number)", " Sets the result of a callback function to the value number. Alias for\n `lsqlite3.Context:result_double()`."}, {"result_error", "function(self: Context, err: any)", " Sets the result of a callback function to the error value in `err`."}, {"result_int", "function(self: Context, number: number)", " Sets the result of a callback function to the integer `number`"}, {"result_null", "function(self: Context)", " Sets the result of a callback function to `nil`."}, {"result_text", "function(self: Context, str: string)", " Sets the result of a callback function to the string in `str`."}, {"user_data", "function(self: Context): any", " Returns the userdata parameter given in the call to install the callback\n function (see db:create_aggregate() and db:create_function() for details)."}}, line=0, name="Context"}, {description=" After opening a database with `lsqlite3.open()` or `lsqlite3.open_memory()`\n the returned database object should be used for all further method calls in\n connection with that database.", fields={{"busy_handler", "function(self: Database, func?: function(udata: any, tries: number), udata?: any)", " Sets or removes a busy handler for a database.\n The handler function is called with two parameters: `udata` and the number\n of (re-)tries for a pending transaction. It should return `nil`, `false` or\n `0` if the transaction is to be aborted. All other values will result in\n another attempt to perform the transaction. (See the SQLite documentation\n for important hints about writing busy handlers.)"}, {"busy_timeout", "function(self: Database, milliseconds: number)", " Sets a busy handler that waits for `milliseconds` if a transaction cannot proceed.\n Calling this function will remove any busy handler set by `db:busy_handler()`;\n calling it with an argument less than or equal to `0` will turn off all busy handlers."}, {"changes", "function(self: Database): number", " Only changes that are directly specified by INSERT, UPDATE, or DELETE\n statements are counted. Auxiliary changes caused by triggers are not\n counted. Use `db:total_changes()` to find the total number of changes."}, {"close", "function(self: Database): number", " Closes a database. All SQL statements prepared using `db:prepare()` should\n have been finalized before this function is called. The function returns\n `lsqlite3.OK` on success or else a numerical error code."}, {"close_vm", "function(self: Database, temponly?: boolean)", " Finalizes all statements that have not been explicitly finalized. If\n `temponly` is `true`, only internal, temporary statements are finalized."}, {"commit_hook", "function(self: Database, func: function(udata: any), udata: any)", " This function installs a `commit_hook` callback handler.\n If `func` returns `false` or `nil` the COMMIT is allowed to proceed,\n otherwise the COMMIT is converted to a ROLLBACK.\n See: `db:rollback_hook` and `db:update_hook`"}, {"create_aggregate", "function(self: Database, name: string, nargs: number, step: function(ctx: Context, ...: string | number), final: function(ctx: Context), userdata?: any): boolean", " It should accept a function context (see Methods for callback contexts) plus\n the same number of parameters as given in `nargs`.\n It receives one argument, the function context.\n The function context can be used inside the two callback functions to\n communicate with SQLite3. Here is a simple example:\n     db:exec[=[\n         CREATE TABLE numbers(num1,num2);\n         INSERT INTO numbers VALUES(1,11);\n         INSERT INTO numbers VALUES(2,22);\n         INSERT INTO numbers VALUES(3,33);\n     ]=]\n     local num_sum=0\n     local function oneRow(context, num)  -- add one column in all rows\n         num_sum = num_sum + num\n     end\n     local function afterLast(context)   -- return sum after last row has been processed\n         context:result_number(num_sum)\n         num_sum = 0\n     end\n     db:create_aggregate(\"do_the_sums\", 1, oneRow, afterLast)\n     for sum in db:urows('SELECT do_the_sums(num1) FROM numbers') do print(\"Sum of col 1:\",sum) end\n     for sum in db:urows('SELECT do_the_sums(num2) FROM numbers') do print(\"Sum of col 2:\",sum) end\n This prints:\n     Sum of col 1:   6\n     Sum of col 2:   66"}, {"create_collation", "function(self: Database, name: string, func: (function(s1: string, s2: string): number))", " This creates a collation callback. A collation callback is used to establish\n a collation order, mostly for string comparisons and sorting purposes.\n A simple example:\n    local function collate(s1,s2)\n      s1=s1:lower()\n      s2=s2:lower()\n      if s1==s2 then return 0\n      elseif s1<s2 then return -1\n      else return 1 end\n    end\n    db:exec[=[\n      CREATE TABLE test(id INTEGER PRIMARY KEY,content COLLATE CINSENS);\n      INSERT INTO test VALUES(NULL,'hello world');\n      INSERT INTO test VALUES(NULL,'Buenos dias');\n      INSERT INTO test VALUES(NULL,'HELLO WORLD');\n    ]=]\n    db:create_collation('CINSENS',collate)\n    for row in db:nrows('SELECT * FROM test') do\n      print(row.id, row.content)\n    end"}, {"create_function", "function(self: Database, name: string, nargs: number, func: function(ctx: Context, ...: any), userdata?: any): boolean", " This function creates a callback function. Callback function are called by\n SQLite3 once for every row in a query.\n It should accept a function context (see Methods for callback contexts) plus\n the same number of parameters as given in `nargs`.\n Here is an example:\n     db:exec'CREATE TABLE test(col1,col2,col3)'\n     db:exec'INSERT INTO test VALUES(1,2,4)'\n     db:exec'INSERT INTO test VALUES(2,4,9)'\n     db:exec'INSERT INTO test VALUES(3,6,16)'\n     db:create_function('sum_cols',3,function(ctx,a,b,c)\n       ctx:result_number(a+b+c)\n     end))\n     for col1,col2,col3,sum in db:urows('SELECT *,sum_cols(col1,col2,col3) FROM test') do\n       util.printf('%2i+%2i+%2i=%2i\\n',col1,col2,col3,sum)\n     end"}, {"db_filename", "function(self: Database, name: string): string | nil", " If there is no attached database name on the database connection, then no value is\n returned; if database name is a temporary or in-memory database, then an\n empty string is returned."}, {"deserialize", "function(self: Database, s: string)", " Deserializes data from a string which was created by `db:serialize`."}, {"errcode", "function(self: Database): number", ""}, {"errmsg", "function(self: Database): string", ""}, {"exec", "function(self: Database, sql: string, func?: (function(udata: any, cols: number, values: {string}, names: {string}): number), udata?: any)", ""}, {"interrupt", "function(self: Database)", " This function causes any pending database operation to abort and return at\n the next opportunity."}, {"isopen", "function(self: Database): boolean", ""}, {"last_insert_rowid", "function(self: Database): number", " Each row in an SQLite table has a unique 64-bit signed integer key called\n the rowid. This id is always available as an undeclared column named ROWID,\n OID, or _ROWID_. If the table has a column of type INTEGER PRIMARY KEY then\n that column is another alias for the rowid.\n If an INSERT occurs within a trigger, then the rowid of the inserted row is\n returned as long as the trigger is running. Once the trigger terminates, the\n value returned reverts to the last value inserted before the trigger fired."}, {"nrows", "function(self: Database, sql: string): function(vm: VM), VM", " Creates an iterator that returns the successive rows selected by the\n SQL statement given in string `sql`. Each call to the iterator\n returns a table in which the named fields correspond to the columns\n in the database. Here is an example:\n     db:exec[=[\n         CREATE TABLE numbers(num1,num2);\n         INSERT INTO numbers VALUES(1,11);\n         INSERT INTO numbers VALUES(2,22);\n         INSERT INTO numbers VALUES(3,33);\n     ]=]\n     for a in db:nrows('SELECT * FROM numbers') do table.print(a) end\n This script prints:\n     num2: 11\n     num1: 1\n     num2: 22\n     num1: 2\n     num2: 33\n     num1: 3"}, {"prepare", "function(self: Database, sql: string): Statement", " This function compiles the SQL statement in string sql into an internal\n representation and returns this as userdata. The returned object should be\n used for all further method calls in connection with this specific SQL\n statement.\n See https://lua.sqlite.org/home/doc/tip/doc/lsqlite3.wiki#methods_for_prepared_statements for details."}, {"readonly", "function(self: Database, name?: string): boolean, string | nil", " Returns `true` if the database `name` of connection `db` is read-only,\n `false` if it is read/write. Returns `nil` plus an error message if\n `name` is not the name of a database on connection `db`."}, {"rollback_hook", "function(self: Database, func: function(udata: any), udata: any)", " This function installs a rollback_hook callback handler.\n See: `db:commit_hook` and `db:update_hook`"}, {"rows", "function(self: Database, sql: string): function, VM", " Creates an iterator that returns the successive rows selected by the SQL\n statement given in string `sql`. Each call to the iterator returns a table in\n which the numerical indices 1 to n correspond to the selected columns 1 to n in\n the database. Here is an example:\n     db:exec[=[\n         CREATE TABLE numbers(num1,num2);\n         INSERT INTO numbers VALUES(1,11);\n         INSERT INTO numbers VALUES(2,22);\n         INSERT INTO numbers VALUES(3,33);\n     ]=]\n     for a in db:rows('SELECT * FROM numbers') do table.print(a) end\n This script prints:\n     1: 1\n     2: 11\n     1: 2\n     2: 22\n     1: 3\n     2: 33"}, {"serialize", "function(self: Database): string | nil", " Serialize a database to be restored later with `Database:deserialize`."}, {"total_changes", "function(self: Database): number", " This includes UPDATE, INSERT and DELETE statements executed as part of trigger\n programs. All changes are counted as soon as the statement that produces them\n is completed by calling either `stmt:reset()` or `stmt:finalize()`."}, {"update_hook", "function(self: Database, func: function(udata: any, op: number, db: Database, name: string, rowid: number), udata: any)", " This function installs an update_hook Data Change Notification\n Callback handler. See: `db:commit_hook` and `db:rollback_hook`\n whenever a row is updated, inserted or deleted. This callback\n receives five arguments: the first is the `udata` argument used\n when the callback was installed; the second is an integer\n indicating the operation that caused the callback to be invoked\n (one of `lsqlite3.UPDATE`, `lsqlite3.INSERT`, or\n `lsqlite3.DELETE`). The third and fourth arguments are the\n database and table name containing the affected row. The final\n callback parameter is the rowid of the row. In the case of an\n update, this is the rowid after the update takes place."}, {"urows", "function(self: Database, sql: string): function, VM", " Creates an iterator that returns the successive rows selected by the SQL\n statement given in string sql. Each call to the iterator returns the values\n that correspond to the columns in the currently selected row.\n Here is an example:\n     db:exec[=[\n         CREATE TABLE numbers(num1,num2);\n         INSERT INTO numbers VALUES(1,11);\n         INSERT INTO numbers VALUES(2,22);\n         INSERT INTO numbers VALUES(3,33);\n     ]=]\n     for num1,num2 in db:urows('SELECT * FROM numbers') do print(num1,num2) end\n This script prints:\n     1       11\n     2       22\n     3       33"}, {"wal_checkpoint", "function(self: Database, mode?: number, name?: string): number, number, number | nil", ""}, {"wal_hook", "function(self: Database, func?: (function(udata: any, db: Database, name: string, page_count: number): number), udata?: any)", ""}}, line=0, name="Database"}, {description=" After creating a prepared statement with `db:prepare()` the returned statement\n object should be used for all further calls in connection with that statement.", fields={{"bind", "function(self: Statement, n: number, value: string | number | boolean): number", " Binds `value` to statement parameter `n`. If the type of `value` is\n string it is bound as text. If the type of value is number, it is\n bound as an integer or double depending on its subtype using\n `lua_isinteger`. If `value` is a boolean then it is bound as `0` for\n `false` or `1` for `true`. If `value` is `nil` or missing, any\n previous binding is removed."}, {"bind_blob", "function(self: Statement, n: number, blob: string): number", " Binds string `blob` (which can be a binary string) as a blob to\n statement parameter `n`."}, {"bind_names", "function(self: Statement, nametable: table): number, number", " Binds the values in `nametable` to statement parameters. If the\n statement parameters are named (i.e., of the form `\":AAA\"` or\n `\"$AAA\"`) then this function looks for appropriately named fields in\n nametable; if the statement parameters are not named, it looks for\n numerical fields 1 to the number of statement parameters."}, {"bind_parameter_count", "function(self: Statement): any", " When the statement parameters are of the forms `\":AAA\"` or `\"?\"`, then they are\n assigned sequentially increasing numbers beginning with one, so the value\n returned is the number of parameters. However if the same statement parameter\n name is used multiple times, each occurrence is given the same number, so the\n value returned is the number of unique statement parameter names.\n If statement parameters of the form `\"?NNN\"` are used (where `NNN` is an\n integer) then there might be gaps in the numbering and the value returned by\n this interface is the index of the statement parameter with the largest index\n value."}, {"bind_parameter_name", "function(self: Statement, n: number): string | nil", " Statement parameters of the form `\":AAA\"` or `\"@AAA\"` or `\"$VVV\"` have a name\n which is the string `\":AAA\"` or `\"@AAA\"` or `\"$VVV\"`. In other words, the\n initial `\":\"` or `\"$\"` or `\"@\"` is included as part of the name. Parameters of\n the form `\"?\"` or `\"?NNN\"` have no name. The first bound parameter has an index\n of `1`. If the value `n` is out of range or if the `n`-th parameter is nameless,\n then `nil` is returned."}, {"bind_values", "function(self: Statement, ...: string | number): number", " Binds the given values to statement parameters."}, {"columns", "function(self: Statement): number", ""}, {"finalize", "function(self: Statement): number", " This function frees the prepared statement."}, {"get_name", "function(self: Statement, n: any): any", ""}, {"get_named_types", "function(self: Statement): table", ""}, {"type", "function(self: Statement): table", " Alias for `lsqlite3.Statement:get_named_types()`."}, {"get_named_values", "function(self: Statement): table", ""}, {"data", "function(self: Statement): table", " Alias for `lsqlite3.Statement:get_named_values()`."}, {"get_names", "function(self: Statement): {string}", ""}, {"inames", "function(self: Statement): {string}", " Alias for `lsqlite3.Statement:get_names()`."}, {"get_type", "function(self: Statement, n: any): any", ""}, {"get_types", "function(self: Statement): {any}", ""}, {"itypes", "function(self: Statement): {any}", " Alias for `lsqlite3.Statement:get_types()`."}, {"get_unames", "function(self: Statement): {any}", ""}, {"get_utypes", "function(self: Statement): {any}", ""}, {"get_uvalues", "function(self: Statement): {any}", ""}, {"get_value", "function(self: Statement, n: any): any", ""}, {"get_values", "function(self: Statement): {any}", ""}, {"idata", "function(self: Statement): {any}", " Alias for `lsqlite3.Statement:get_values()`."}, {"isopen", "function(self: Statement): boolean", ""}, {"nrows", "function(self: Statement): function", ""}, {"readonly", "function(self: Statement): boolean", " Returns `true` if the prepared statement makes no direct changes to\n the content of the database file, `false` otherwise."}, {"reset", "function(self: Statement)", " This function resets the SQL statement, so that it is ready to be re-executed. Any statement variables that had values bound to them using the `stmt:bind*()` functions retain their values."}, {"rows", "function(self: Statement): function", ""}, {"step", "function(self: Statement): number", " This function must be called to evaluate the (next iteration of the) prepared statement.\n - `lsqlite3.BUSY`: the engine was unable to acquire the locks needed.\n   If the statement is a COMMIT or occurs outside of an explicit transaction,\n   then you can retry the statement. If the statement is not a COMMIT and occurs\n   within a explicit transaction then you should rollback the transaction before\n   continuing.\n - `lsqlite3.DONE`: the statement has finished executing successfully.\n   `stmt:step()` should not be called again on this statement without first\n   calling `stmt:reset()` to reset the virtual machine back to the initial state.\n - `lsqlite3.ROW`: this is returned each time a new row of data is ready for\n    processing by the caller. The values may be accessed using the column access\n    functions. `stmt:step()` can be called again to retrieve the next\n    row of data.\n - `lsqlite3.ERROR`: a run-time error (such as a constraint violation) has\n    occurred. `stmt:step()` should not be called again. More\n    information may be found by calling `db:errmsg()`. A more specific error\n    code (can be obtained by calling `stmt:reset()`.\n - `lsqlite3.MISUSE`: the function was called inappropriately, perhaps because\n    the statement has already been finalized or a previous call to `stmt:step()`\n    has returned `lsqlite3.ERROR` or `lsqlite3.DONE`."}, {"urows", "function(self: Statement): function", " Each iteration returns the values for the current row. This is the prepared\n statement equivalent of `db:urows()`."}, {"last_insert_rowid", "function(self: Statement): any", ""}}, line=0, name="Statement"}, {fields={{"bind", "function(self: VM, index: number, value: string | number | boolean): number", ""}, {"bind_blob", "function(self: VM, index: number, value: string): number", ""}, {"bind_names", "function(self: VM, names: {string}): number", ""}, {"bind_parameter_count", "function(self: VM): number", ""}, {"bind_parameter_name", "function(self: VM, index: number): string", ""}, {"bind_values", "function(self: VM, ...: string | number): number", ""}, {"columns", "function(self: VM): number", ""}, {"finalize", "function(self: VM): number", ""}, {"get_name", "function(self: VM, index: number): string", ""}, {"get_named_types", "function(self: VM): {string}", ""}, {"type", "function(self: VM): {string}", " Alias for `lsqlite3.VM:get_named_types()`."}, {"get_named_values", "function(self: VM): {string | number | nil}", ""}, {"data", "function(self: VM): {string | number | nil}", " Alias for `lsqlite3.VM:get_named_values()`."}, {"get_names", "function(self: VM): {string}", ""}, {"inames", "function(self: VM): {string}", " Alias for `lsqlite3.VM:get_names()`."}, {"get_type", "function(self: VM, index: number): string", ""}, {"get_types", "function(self: VM): {string}", ""}, {"itypes", "function(self: VM): {string}", " Alias for `lsqlite3.VM:get_types()`."}, {"get_unames", "function(self: VM): string...", ""}, {"get_utypes", "function(self: VM): string...", ""}, {"get_uvalues", "function(self: VM): string | number | nil", ""}, {"get_value", "function(self: VM, index: number): string | number | nil", ""}, {"get_values", "function(self: VM): {string | number | nil}", ""}, {"idata", "function(self: VM): {string | number | nil}", " Alias for `lsqlite3.VM:get_values()`."}, {"isopen", "function(self: VM): boolean", ""}, {"last_insert_rowid", "function(self: VM): number", ""}, {"nrows", "function(self: VM, sql: string): function(self: VM): {string: string | number}", ""}, {"readonly", "function(self: VM): boolean", " Returns `true` if the prepared statement makes no direct changes to\n the content of the database file, `false` otherwise."}, {"reset", "function(self: VM): number", ""}, {"rows", "function(self: VM, sql: string): function(self: VM): {string | number}", ""}, {"step", "function(self: VM): number", ""}, {"urows", "function(self: VM, sql: string): function(self: VM): any...", ""}}, line=0, name="VM"}, {description="Constants defined in the lsqlite3 module.", fields={{"OK", "number", " The `lsqlite3.OK` result code means that the operation was successful\n and that there were no errors. Most other result codes indicate an\n error."}, {"ERROR", "number", " The `lsqlite3.ERROR` result code is a generic error code that is used\n when no other more specific error code is available."}, {"INTERNAL", "number", " The `lsqlite3.INTERNAL` result code indicates an internal malfunction.\n In a working version of SQLite, an application should never see this\n result code. If application does encounter this result code, it shows\n that there is a bug in the database engine.\n SQLite does not currently generate this result code. However,\n application-defined SQL functions or virtual tables, or VFSes, or other\n extensions might cause this result code to be returned."}, {"PERM", "number", " The `lsqlite3.PERM` result code indicates that the requested access mode\n for a newly created database could not be provided."}, {"ABORT", "number", " The `lsqlite3.ABORT` result code indicates that an operation was aborted\n prior to completion, usually be application request. See also:\n `lsqlite3.INTERRUPT`.\n If the callback function to `exec()` returns non-zero, then `exec()`\n will return `lsqlite3.ABORT`.\n If a ROLLBACK operation occurs on the same database connection as a\n pending read or write, then the pending read or write may fail with an\n `lsqlite3.ABORT` error."}, {"BUSY", "number", " The lsqlite3.BUSY result code indicates that the database file could not\n be written (or in some cases read) because of concurrent activity by\n some other database connection, usually a database connection in a\n separate process.\n For example, if process A is in the middle of a large write transaction\n and at the same time process B attempts to start a new write\n transaction, process B will get back an `lsqlite3.BUSY` result because\n SQLite only supports one writer at a time. Process B will need to wait\n for process A to finish its transaction before starting a new\n transaction. The `db:busy_timeout()` and `db:busy_handler()` interfaces\n are available to process B to help it deal with `lsqlite3.BUSY` errors.\n An `lsqlite3.BUSY` error can occur at any point in a transaction: when\n the transaction is first started, during any write or update operations,\n or when the transaction commits. To avoid encountering `lsqlite3.BUSY`\n errors in the middle of a transaction, the application can use\n `BEGIN IMMEDIATE` instead of just `BEGIN` to start a transaction. The\n `BEGIN IMMEDIATE` command might itself return `lsqlite3.BUSY`, but if it\n succeeds, then SQLite guarantees that no subsequent operations on the same database through the next COMMIT will return `lsqlite3.BUSY`.\n The `lsqlite3.BUSY` result code differs from `lsqlite3.LOCKED` in that\n `lsqlite3.BUSY` indicates a conflict with a separate database\n connection, probably in a separate process, whereas `lsqlite3.LOCKED`\n indicates a conflict within the same database connection (or sometimes\n a database connection with a shared cache)."}, {"LOCKED", "number", " The `lsqlite3.LOCKED` result code indicates that a write operation could\n not continue because of a conflict within the same database connection\n or a conflict with a different database connection that uses a shared\n cache.\n For example, a DROP TABLE statement cannot be run while another thread\n is reading from that table on the same database connection because\n dropping the table would delete the table out from under the concurrent\n reader.\n The `lsqlite3.LOCKED` result code differs from `lsqlite3.BUSY` in that\n `lsqlite3.LOCKED` indicates a conflict on the same database connection\n (or on a connection with a shared cache) whereas `lsqlite3.BUSY`\n indicates a conflict with a different database connection, probably in\n a different process."}, {"NOMEM", "number", " The `lsqlite3.NOMEM` result code indicates that SQLite was unable to\n allocate all the memory it needed to complete the operation. In other\n words, an internal call to `sqlite3_malloc()` or `sqlite3_realloc()` has\n failed in a case where the memory being allocated was required in order\n to continue the operation."}, {"READONLY", "number", " The `lsqlite3.READONLY` result code is returned when an attempt is made\n to alter some data for which the current database connection does not\n have write permission."}, {"INTERRUPT", "number", " The `lsqlite3.INTERRUPT` result code indicates that an operation was\n interrupted by the `sqlite3_interrupt()` interface. See also:\n `lsqlite3.ABORT`"}, {"IOERR", "number", " The `lsqlite3.IOERR` result code says that the operation could not\n finish because the operating system reported an I/O error.\n A full disk drive will normally give an `lsqlite3.FULL` error rather\n than an `lsqlite3.IOERR` error.\n There are many different extended result codes for I/O errors that\n identify the specific I/O operation that failed."}, {"CORRUPT", "number", " The `lsqlite3.CORRUPT` result code indicates that the database file has\n been corrupted. See [How To Corrupt Your Database Files](https://www.sqlite.org/lockingv3.html#how_to_corrupt)\n for further discussion on how corruption can occur."}, {"NOTFOUND", "number", " The `lsqlite3.NOTFOUND` result code is exposed in three ways:\n `lsqlite3.NOTFOUND` can be returned by the `sqlite3_file_control()`\n interface to indicate that the file control opcode passed as the third\n argument was not recognized by the underlying VFS.\n `lsqlite3.NOTFOUND` can also be returned by the xSetSystemCall() method\n of an sqlite3_vfs object.\n `lsqlite3.NOTFOUND` an be returned by sqlite3_vtab_rhs_value() to\n indicate that the right-hand operand of a constraint is not available\n to the xBestIndex method that made the call.\n The `lsqlite3.NOTFOUND` result code is also used internally by the\n SQLite implementation, but those internal uses are not exposed to the\n application."}, {"FULL", "number", " The `lsqlite3.FULL` result code indicates that a write could not\n complete because the disk is full. Note that this error can occur when\n trying to write information into the main database file, or it can also\n occur when writing into temporary disk files.\n Sometimes applications encounter this error even though there is an\n abundance of primary disk space because the error occurs when writing\n into temporary disk files on a system where temporary files are stored\n on a separate partition with much less space that the primary disk."}, {"CANTOPEN", "number", " The `lsqlite3.CANTOPEN` result code indicates that SQLite was unable to\n open a file. The file in question might be a primary database file or\n one of several temporary disk files."}, {"PROTOCOL", "number", " The `lsqlite3.PROTOCOL` result code indicates a problem with the file\n locking protocol used by SQLite. The `lsqlite3.PROTOCOL` error is\n currently only returned when using WAL mode and attempting to start a\n new transaction. There is a race condition that can occur when two\n separate database connections both try to start a transaction at the\n same time in WAL mode. The loser of the race backs off and tries again,\n after a brief delay. If the same connection loses the locking race\n dozens of times over a span of multiple seconds, it will eventually give\n up and return `lsqlite3.PROTOCOL`. The `lsqlite3.PROTOCOL` error should\n appear in practice very, very rarely, and only when there are many\n separate processes all competing intensely to write to the same\n database."}, {"EMPTY", "number", " The `lsqlite3.EMPTY` result code is not currently used."}, {"SCHEMA", "number", " The `lsqlite3.SCHEMA` result code indicates that the database schema has\n changed. This result code can be returned from `Statement:step()`. If\n the database schema was changed by some other process in between the\n time that the statement was prepared and the time the statement was run,\n this error can result.\n The statement is automatically re-prepared if the schema changes, up to\n `SQLITE_MAX_SCHEMA_RETRY` times (default: 50). The `step()` interface\n will only return `lsqlite3.SCHEMA` back to the application if the\n failure persists after these many retries."}, {"TOOBIG", "number", " The `lsqlite3.TOOBIG` error code indicates that a string or BLOB was too\n large. The default maximum length of a string or BLOB in SQLite is\n 1,000,000,000 bytes. This maximum length can be changed at compile-time\n using the `SQLITE_MAX_LENGTH` compile-time option. The `lsqlite3.TOOBIG`\n error results when SQLite encounters a string or BLOB that exceeds the\n compile-time limit.\n The `lsqlite3.TOOBIG` error code can also result when an oversized SQL\n statement is passed into one of the `db:prepare()` interface. The\n maximum length of an SQL statement defaults to a much smaller value of\n 1,000,000,000 bytes."}, {"CONSTRAINT", "number", " The `lsqlite3.CONSTRAINT` error code means that an SQL constraint\n violation occurred while trying to process an SQL statement. Additional\n information about the failed constraint can be found by consulting the\n accompanying error message (returned via `errmsg()`) or by looking at\n the extended error code.\n The `lsqlite3.CONSTRAINT` code can also be used as the return value from\n the `xBestIndex()` method of a virtual table implementation. When\n `xBestIndex()` returns `lsqlite3.CONSTRAINT`, that indicates that the\n particular combination of inputs submitted to `xBestIndex()` cannot\n result in a usable query plan and should not be given further\n consideration."}, {"MISMATCH", "number", " SQLite is normally very forgiving about mismatches between the type of a\n value and the declared type of the container in which that value is to\n be stored. For example, SQLite allows the application to store a large\n BLOB in a column with a declared type of BOOLEAN. But in a few cases,\n SQLite is strict about types. The `lsqlite3.MISMATCH` error is returned\n in those few cases when the types do not match.\n The rowid of a table must be an integer. Attempt to set the rowid to\n anything other than an integer (or a NULL which will be automatically\n converted into the next available integer rowid) results in an\n `lsqlite3.MISMATCH` error."}, {"MISUSE", "number", " The `lsqlite3.MISUSE` return code might be returned if the application\n uses any SQLite interface in a way that is undefined or unsupported. For\n example, using a prepared statement after that prepared statement has\n been finalized might result in an `lsqlite3.MISUSE` error.\n SQLite tries to detect misuse and report the misuse using this result\n code. However, there is no guarantee that the detection of misuse will\n be successful. Misuse detection is probabilistic. Applications should\n never depend on an `lsqlite3.MISUSE` return value.\n If SQLite ever returns `lsqlite3.MISUSE` from any interface, that means\n that the application is incorrectly coded and needs to be fixed. Do not\n ship an application that sometimes returns `lsqlite3.MISUSE` from a\n standard SQLite interface because that application contains potentially\n serious bugs."}, {"NOLFS", "number", " The `lsqlite3.NOLFS` error can be returned on systems that do not\n support large files when the database grows to be larger than what the\n filesystem can handle. \"NOLFS\" stands for \"NO Large File Support\"."}, {"FORMAT", "number", " The `lsqlite3.FORMAT` error code is not currently used by SQLite."}, {"RANGE", "number", " The `lsqlite3.RANGE` error indices that the parameter number argument to\n one of the `bind` routines or the column number in one of the `column`\n routines is out of range."}, {"NOTADB", "number", " When attempting to open a file, the `lsqlite3.NOTADB` error indicates\n that the file being opened does not appear to be an SQLite database\n file."}, {"ROW", "number", " The `lsqlite3.ROW` result code returned by sqlite3_step() indicates that\n another row of output is available."}, {"DONE", "number", " The `lsqlite3.DONE` result code indicates that an operation has\n completed. The `lsqlite3.DONE` result code is most commonly seen as a\n return value from `step()` indicating that the SQL statement has run to\n completion, but `lsqlite3.DONE` can also be returned by other multi-step\n interfaces."}, {"CREATE_INDEX", "number", ""}, {"CREATE_TABLE", "number", ""}, {"CREATE_TEMP_INDEX", "number", ""}, {"CREATE_TEMP_TABLE", "number", ""}, {"CREATE_TEMP_TRIGGER", "number", ""}, {"CREATE_TEMP_VIEW", "number", ""}, {"CREATE_TRIGGER", "number", ""}, {"CREATE_VIEW", "number", ""}, {"DELETE", "number", ""}, {"DROP_INDEX", "number", ""}, {"DROP_TABLE", "number", ""}, {"DROP_TEMP_INDEX", "number", ""}, {"DROP_TEMP_TABLE", "number", ""}, {"DROP_TEMP_TRIGGER", "number", ""}, {"DROP_TEMP_VIEW", "number", ""}, {"DROP_TRIGGER", "number", ""}, {"DROP_VIEW", "number", ""}, {"INSERT", "number", ""}, {"PRAGMA", "number", ""}, {"READ", "number", ""}, {"SELECT", "number", ""}, {"TRANSACTION", "number", ""}, {"UPDATE", "number", ""}, {"ATTACH", "number", ""}, {"DETACH", "number", ""}, {"ALTER_TABLE", "number", ""}, {"REINDEX", "number", ""}, {"ANALYZE", "number", ""}, {"CREATE_VTABLE", "number", ""}, {"DROP_VTABLE", "number", ""}, {"FUNCTION", "number", ""}, {"SAVEPOINT", "number", ""}, {"OPEN_CREATE", "number", " The database is created if it does not already exist."}, {"OPEN_PRIVATECACHE", "number", " The database is opened with shared cache disabled, overriding the\n default shared cache setting provided by sqlite3_enable_shared_cache()."}, {"OPEN_FULLMUTEX", "number", " The new database connection will use the \"serialized\" threading mode.\n This means the multiple threads can safely attempt to use the same\n database connection at the same time. (Mutexes will block any actual\n concurrency, but in this mode there is no harm in trying.)"}, {"OPEN_NOMUTEX", "number", " The new database connection will use the \"multi-thread\" threading mode.\n This means that separate threads are allowed to use SQLite at the same\n time, as long as each thread is using a different database connection."}, {"OPEN_MEMORY", "number", " The database will be opened as an in-memory database. The database is\n named by the \"filename\" argument for the purposes of cache-sharing, if\n shared cache mode is enabled, but the \"filename\" is otherwise ignored."}, {"OPEN_URI", "number", " The filename can be interpreted as a URI if this flag is set. See\n https://www.sqlite.org/c3ref/open.html"}, {"OPEN_READWRITE", "number", " The database is opened for reading and writing if possible, or reading\n only if the file is write protected by the operating system. In either\n case the database must already exist, otherwise an error is returned."}, {"OPEN_READONLY", "number", " The database is opened in read-only mode. If the database does not\n already exist, an error is returned."}, {"OPEN_SHAREDCACHE", "number", " The database is opened shared cache enabled, overriding the default\n shared cache setting provided by sqlite3_enable_shared_cache(). The use\n of shared cache mode is discouraged and hence shared cache capabilities\n may be omitted from many builds of SQLite. In such cases, this option is\n a no-op."}, {"TEXT", "number", ""}, {"BLOB", "number", ""}, {"NULL", "number", ""}, {"FLOAT", "number", ""}, {"INTEGER", "number", ""}, {"CONFIG_SINGLETHREAD", "number", ""}, {"CONFIG_MULTITHREAD", "number", ""}, {"CONFIG_SERIALIZED", "number", ""}, {"CONFIG_LOG", "number", ""}, {"CHECKPOINT_PASSIVE", "number", " for any database readers or writers to finish. See `db:wal_checkpoint`."}, {"CHECKPOINT_FULL", "number", " reading from the most recent database snapshot, then checkpoints all\n frames. See `db:wal_checkpoint`."}, {"CHECKPOINT_RESTART", "number", " blocks until all readers are reading from the database file only.\n See `db:wal_checkpoint`."}, {"CHECKPOINT_TRUNCATE", "number", " truncates the log file before returning. See `db:wal_checkpoint`."}}, line=0, name="lsqlite3 Constants"}}}, ["cosmo.path"]={examples={}, file="lib/types/cosmo/path.d.tl", functions={{description=" Strips final component of path, e.g.\n     path      │ dirname\n     ───────────────────\n     .         │ .\n     ..        │ .\n     /         │ /\n     usr       │ .\n     /usr/     │ /\n     /usr/lib  │ /usr\n     /usr/lib/ │ /usr", is_local=false, line=0, name="dirname", params={{name="str", param_type="string"}}, returns={{return_type="string"}}, signature="(str: string): string"}, {description=" Returns final component of path, e.g.\n     path      │ basename\n     ─────────────────────\n     .         │ .\n     ..        │ ..\n     /         │ /\n     usr       │ usr\n     /usr/     │ usr\n     /usr/lib  │ lib\n     /usr/lib/ │ lib", is_local=false, line=0, name="basename", params={{name="str", param_type="string"}}, returns={{return_type="string"}}, signature="(str: string): string"}, {description=" Concatenates path components, e.g.\n     x         │ y        │ joined\n     ─────────────────────────────────\n     /         │ /        │ /\n     /usr      │ lib      │ /usr/lib\n     /usr/     │ lib      │ /usr/lib\n     /usr/lib  │ /lib     │ /lib\n You may specify 1+ arguments.\n Specifying no arguments will raise an error. If `nil` arguments are specified,\n then they're skipped over. If exclusively `nil` arguments are passed, then `nil`\n is returned. Empty strings behave similarly to `nil`, but unlike `nil` may\n coerce a trailing slash.", is_local=false, line=0, name="join", params={{name="str", param_type="string"}, {name="...", param_type="string"}}, returns={{return_type="string | nil"}}, signature="(str?: string, ...: string): string | nil"}, {description=" Returns `true` if path exists.\n This function is inclusive of regular files, directories, and special files.\n Symbolic links are followed are resolved. On error, `false` is returned.", is_local=false, line=0, name="exists", params={{name="path", param_type="string"}}, returns={{return_type="boolean"}}, signature="(path: string): boolean"}, {description=" Returns `true` if path exists and is regular file.\n Symbolic links are not followed. On error, `false` is returned.", is_local=false, line=0, name="isfile", params={{name="path", param_type="string"}}, returns={{return_type="boolean"}}, signature="(path: string): boolean"}, {description=" Returns `true` if path exists and is directory.\n Symbolic links are not followed. On error, `false` is returned.", is_local=false, line=0, name="isdir", params={{name="path", param_type="string"}}, returns={{return_type="boolean"}}, signature="(path: string): boolean"}, {description=" Returns `true` if path exists and is symbolic link.\n Symbolic links are not followed. On error, `false` is returned.", is_local=false, line=0, name="islink", params={{name="path", param_type="string"}}, returns={{return_type="boolean"}}, signature="(path: string): boolean"}}, module_doc="Type declarations for the `path` module.", records={}}, ["cosmo.re"]={examples={}, file="lib/types/cosmo/re.d.tl", functions={{description=" Searches for regular expression match in text.\n This is a shorthand notation roughly equivalent to:\n     local preg = assert(re.compile(regex))\n     local match, captures = preg:search(text)\n On a match, returns the whole matched substring plus a table of the\n parenthesized capture groups. A no-match returns a bare `nil`. A bad pattern\n (compile failure) or a regex engine failure returns `nil, err`.\n - `re.BASIC`\n - `re.ICASE`\n - `re.NEWLINE`\n - `re.NOSUB`\n - `re.NOTBOL`\n - `re.NOTEOL`\n This has exponential complexity. Please use `re.compile()` to compile your regular expressions once from `/.init.lua`. This API exists for convenience. This isn't recommended for prod.\n This uses POSIX extended syntax by default.", is_local=false, line=0, name="search", params={{name="regex", param_type="string"}, {name="text", param_type="string"}, {name="flags", param_type="number"}}, returns={{return_type="string"}, {return_type="{string}"}, {return_type="string | nil"}}, signature="(regex: string, text: string, flags?: number): string, {string}, string | nil"}, {description=" Compiles regular expression.\n - `re.BASIC`\n - `re.ICASE`\n - `re.NEWLINE`\n - `re.NOSUB`\n This has an O(2^𝑛) cost. Consider compiling regular expressions once\n from your `/.init.lua` file.\n If regex is an untrusted user value, then `unix.setrlimit` should be\n used to impose cpu and memory quotas for security.\n This uses POSIX extended syntax by default.", is_local=false, line=0, name="compile", params={{name="regex", param_type="string"}, {name="flags", param_type="number"}}, returns={{return_type="Regex"}, {return_type="string | nil"}}, signature="(regex: string, flags?: number): Regex, string | nil"}}, module_doc="Type declarations for the `re` module.", records={{fields={{"search", "function(self: Regex, str: string, flags?: number): string, {string}, string | nil", " Executes precompiled regular expression.\n On a match, returns the whole matched substring plus a table of the\n parenthesized capture groups (an empty table when the pattern has no groups).\n A no-match is not an error: it returns a single bare `nil`, so the idiomatic\n `if match then` works. Only a genuine regex engine failure (e.g. running out\n of memory) returns `nil, err`. Flags may contain `re.NOTBOL` or `re.NOTEOL`\n to indicate whether or not text should be considered at the start and/or end\n of a line.\n - `re.NOTBOL`\n - `re.NOTEOL`\n This has an O(𝑛) cost."}}, line=0, name="Regex"}, {description="Constants defined in the re module.", fields={{"NOMATCH", "number", " No match"}, {"BADPAT", "number", " Invalid regex"}, {"ECOLLATE", "number", " Unknown collating element"}, {"ECTYPE", "number", " Unknown character class name"}, {"EESCAPE", "number", " Trailing backslash"}, {"ESUBREG", "number", " Invalid back reference"}, {"EBRACK", "number", " Missing ]"}, {"EPAREN", "number", " Missing )"}, {"EBRACE", "number", " Missing }"}, {"BADBR", "number", " Invalid contents of {}"}, {"ERANGE", "number", " Invalid character range."}, {"ESPACE", "number", " Out of memory"}, {"BADRPT", "number", " Repetition not preceded by valid expression"}, {"BASIC", "number", " Use this flag if you prefer the default POSIX regex syntax.\n We use extended regex notation by default. For example, an extended regular\n expression for matching an IP address might look like\n `([0-9]*)\\.([0-9]*)\\.([0-9]*)\\.([0-9]*)` whereas with basic syntax it would\n look like `\\([0-9]*\\)\\.\\([0-9]*\\)\\.\\([0-9]*\\)\\.\\([0-9]*\\)`.\n This flag may only be used with `re.compile` and `re.search`."}, {"ICASE", "number", " Use this flag if you prefer the default POSIX regex syntax. We use extended\n  regex notation by default. For example, an extended regular expression for\n matching an IP address might look like `([0-9]*)\\.([0-9]*)\\.([0-9]*)\\.([0-9]*)`\n whereas with basic syntax it would look like `\\([0-9]*\\)\\.\\([0-9]*\\)\\.\\([0-9]*\\)\\.\\([0-9]*\\)`.\n This flag may only be used with `re.compile` and `re.search`."}, {"NEWLINE", "number", " Use this flag to change the handling of NEWLINE (\\x0a) characters. When this\n flag is set, (1) a NEWLINE shall not be matched by a \".\" or any form of a\n non-matching list, (2) a \"^\" shall match the zero-length string immediately\n after a NEWLINE (regardless of `re.NOTBOL`), and (3) a \"$\" shall match the\n zero-length string immediately before a NEWLINE (regardless of `re.NOTEOL`)."}, {"NOSUB", "number", " Causes `re.search` to only report success and failure. This is reported via\n the API by returning empty string for success. This flag may only be used\n ` with `re.compile` and `re.search`."}, {"NOTBOL", "number", " The first character of the string pointed to by string is not the beginning\n of the line. This flag may only be used with `re.search` and `regex_t*:search`."}, {"NOTEOL", "number", " The last character of the string pointed to by string is not the end of the\n line. This flag may only be used with `re.search` and `regex_t*:search`."}}, line=0, name="re Constants"}}}, ["cosmo.repl"]={examples={}, file="lib/types/cosmo/repl.d.tl", functions={{description=" Starts an interactive read-eval-print-loop (REPL) on standard input\n and output, with line editing, history, and tab completion. Each\n input line is evaluated as an expression (printing its results) or\n as a statement. The loop runs until end of input (Ctrl-D). Takes no\n arguments and returns nothing.", is_local=false, line=0, name="start", params={}, returns={}, signature="()"}}, module_doc="Type declarations for the `repl` module.", records={}}, ["cosmo.unix"]={examples={}, file="lib/types/cosmo/unix.d.tl", functions={{description=" Opens file.\n Returns a file descriptor integer that needs to be closed, e.g.\n     fd = assert(unix.open(\"/etc/passwd\", unix.O_RDONLY))\n     print(unix.read(fd))\n     unix.close(fd)\n `flags` should have one of:\n - `O_RDONLY`:     open for reading (default)\n - `O_WRONLY`:     open for writing\n - `O_RDWR`:       open for reading and writing\n The following values may also be OR'd into `flags`:\n  - `O_CREAT`      create file if it doesn't exist\n  - `O_TRUNC`      automatic ftruncate(fd,0) if exists\n  - `O_CLOEXEC`    automatic close() upon execve()\n  - `O_EXCL`       exclusive access (see below)\n  - `O_APPEND`     open file for append only\n  - `O_NONBLOCK`   asks read/write to fail with EAGAIN rather than block\n  - `O_DIRECTORY`  useful for stat'ing (hint on UNIX but required on NT)\n  - `O_NOFOLLOW`   fail if it's a symlink (zero on Windows)\n  - `O_UNLINK`     automatically delete file upon close()\n  - `O_SYNC`       makes file operations synchronize appropriately\n  - `O_RSYNC`      synchronize read() operations\n  - `O_DSYNC`      synchronize write() operations\n  - `O_DIRECT`     it's complicated (not supported on Apple and OpenBSD)\n  - `O_NOATIME`    don't record access time (zero on non-Linux)\n  There are three regular combinations for the above flags:\n  - `O_RDONLY`: Opens existing file for reading. If it doesn't exist\n    then nil is returned and errno will be `ENOENT` (or in some other\n    cases `ENOTDIR`).\n  - `O_WRONLY|O_CREAT|O_TRUNC`: Creates file. If it already exists,\n    then the existing copy is destroyed and the opened file will\n    start off with a length of zero. This is the behavior of the\n    traditional creat() system call.\n  - `O_WRONLY|O_CREAT|O_EXCL`: Create file only if doesn't exist\n    already. If it does exist then `nil` is returned along with\n    `errno` set to `EEXIST`.\n `dirfd` defaults to to `unix.AT_FDCWD` and may optionally be set to\n a directory file descriptor to which `path` is relative.\n Returns `ENOENT` if `path` doesn't exist.\n Returns `ENOTDIR` if `path` contained a directory component that\n wasn't a directory\n .", is_local=false, line=0, name="open", params={{name="path", param_type="string"}, {name="flags", param_type="number"}, {name="mode", param_type="number"}, {name="dirfd", param_type="number"}}, returns={{return_type="number"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(path: string, flags: number, mode?: number, dirfd?: number): number, string | nil, number | nil"}, {description=" Closes file descriptor.\n This function should never be called twice for the same file\n descriptor, regardless of whether or not an error happened. The file\n descriptor is always gone after close is called. So it technically\n always succeeds, but that doesn't mean an error should be ignored.\n For example, on NFS a close failure could indicate data loss.\n Closing does not mean that scheduled i/o operations have been\n completed. You'd need to use fsync() or fdatasync() beforehand to\n ensure that. You shouldn't need to do that normally, because our\n close implementation guarantees a consistent view, since on systems\n where it isn't guaranteed (like Windows) close will implicitly sync.\n File descriptors are automatically closed on exit().\n Returns `EBADF` if `fd` wasn't valid.\n Returns `EINTR` possibly maybe.\n Returns `EIO` if an i/o error occurred.", is_local=false, line=0, name="close", params={{name="fd", param_type="number"}}, returns={{return_type="boolean"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(fd: number): boolean, string | nil, number | nil"}, {description=" Reads from file descriptor.\n This function returns empty string on end of file. The exception is\n if `bufsiz` is zero, in which case an empty returned string means\n the file descriptor works.", is_local=false, line=0, name="read", params={{name="fd", param_type="number"}, {name="bufsiz", param_type="number"}, {name="offset", param_type="number"}}, returns={{return_type="string"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(fd: number, bufsiz?: number, offset?: number): string, string | nil, number | nil"}, {description=" Writes to file descriptor.", is_local=false, line=0, name="write", params={{name="fd", param_type="number"}, {name="data", param_type="string"}, {name="offset", param_type="number"}}, returns={{return_type="number"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(fd: number, data: string, offset?: number): number, string | nil, number | nil"}, {description=" Invokes `_Exit(exitcode)` on the process. This will immediately\n halt the current process. Memory will be freed. File descriptors\n will be closed. Any open connections it owns will be reset. This\n function never returns.", is_local=false, line=0, name="exit", params={{name="exitcode", param_type="number"}}, returns={}, signature="(exitcode?: number)"}, {description=" Returns raw environment variables.\n This allocates and constructs the C/C++ `environ` variable as a Lua\n table consisting of string keys and string values.\n This data structure preserves casing. On Windows NT, by convention,\n environment variable keys are treated in a case-insensitive way. It\n is the responsibility of the caller to consider this.\n This data structure preserves valueless variables. It's possible on\n both UNIX and Windows to have an environment variable without an\n equals, even though it's unusual.\n This data structure preserves duplicates. For example, on Windows,\n there's some irregular uses of environment variables such as how the\n command prompt inserts multiple environment variables with empty\n string as keys, for its internal bookkeeping.", is_local=false, line=0, name="environ", params={}, returns={{return_type="{string}"}}, signature="(): {string}"}, {description=" Sets environment variable.\n This wraps the C `setenv()` function to allow Lua scripts to set\n environment variables.", is_local=false, line=0, name="setenv", params={{name="name", param_type="string"}, {name="value", param_type="string"}, {name="overwrite", param_type="boolean"}}, returns={{return_type="boolean"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(name: string, value: string, overwrite?: boolean): boolean, string | nil, number | nil"}, {description=" Unsets environment variable.\n This wraps the C `unsetenv()` function to allow Lua scripts to remove\n environment variables.", is_local=false, line=0, name="unsetenv", params={{name="name", param_type="string"}}, returns={{return_type="boolean"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(name: string): boolean, string | nil, number | nil"}, {description=" Clears all environment variables.\n This wraps the C `clearenv()` function to allow Lua scripts to remove\n all environment variables at once.", is_local=false, line=0, name="clearenv", params={}, returns={{return_type="boolean"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(): boolean, string | nil, number | nil"}, {description=" Gets login name of current user.\n This wraps the C `getlogin()` function to retrieve the login name\n associated with the current session.", is_local=false, line=0, name="getlogin", params={}, returns={{return_type="string"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(): string, string | nil, number | nil"}, {description=" Creates a new process mitosis style.\n This system call returns twice. The parent process gets the nonzero\n pid. The child gets zero.\n Here's a simple usage example of creating subprocesses, where we\n fork off a child worker from a main process hook callback to do some\n independent chores, such as sending an HTTP request back to redbean.\n    -- as soon as server starts, make a fetch to the server\n    -- then signal redbean to shutdown when fetch is complete\n    local onServerStart = function()\n       if assert(unix.fork()) == 0 then\n          local ok, headers, body = Fetch('http://127.0.0.1:8080/test')\n          unix.kill(unix.getppid(), unix.SIGTERM)\n          unix.exit(0)\n       end\n    end\n    OnServerStart = onServerStart\n We didn't need to use `wait()` here, because (a) we want redbean to go\n back to what it was doing before as the `Fetch()` completes, and (b)\n redbean's main process already has a zombie collector. However it's\n a moot point, since once the fetch is done, the child process then\n asks redbean to gracefully shutdown by sending SIGTERM its parent.\n This is actually a situation where we *must* use fork, because the\n purpose of the main redbean process is to call accept() and create\n workers. So if we programmed redbean to use the main process to send\n a blocking request to itself instead, then redbean would deadlock\n and never be able to accept() the client.\n While deadlocking is an extreme example, the truth is that latency\n issues can crop up for the same reason that just cause jitter\n instead, and as such, can easily go unnoticed. For example, if you\n do soemething that takes longer than a few milliseconds from inside\n your redbean heartbeat, then that's a few milliseconds in which\n redbean is no longer concurrent, and tail latency is being added to\n its ability to accept new connections. fork() does a great job at\n solving this.\n If you're not sure how long something will take, then when in doubt,\n fork off a process. You can then report its completion to something\n like SQLite. Redbean makes having lots of processes cheap. On Linux\n they're about as lightweight as what heavyweight environments call\n greenlets. You can easily have 10,000 Redbean workers on one PC.\n Here's some benchmarks for fork() performance across platforms:\n    Linux 5.4 fork      l:     97,200𝑐    31,395𝑛𝑠  [metal]\n    FreeBSD 12 fork     l:    236,089𝑐    78,841𝑛𝑠  [vmware]\n    Darwin 20.6 fork    l:    295,325𝑐    81,738𝑛𝑠  [metal]\n    NetBSD 9 fork       l:  5,832,027𝑐 1,947,899𝑛𝑠  [vmware]\n    OpenBSD 6.8 fork    l: 13,241,940𝑐 4,422,103𝑛𝑠  [vmware]\n    Windows10 fork      l: 18,802,239𝑐 6,360,271𝑛𝑠  [metal]\n One of the benefits of using `fork()` is it creates an isolation\n barrier between the different parts of your app. This can lead to\n enhanced reliability and security. For example, redbean uses fork so\n it can wipe your ssl keys from memory before handing over control to\n request handlers that process untrusted input. It also ensures that\n if your Lua app crashes, it won't take down the server as a whole.\n Hence it should come as no surprise that `fork()` would go slower on\n operating systems that have more security features. So depending on\n your use case, you can choose the operating system that suits you.", is_local=false, line=0, name="fork", params={}, returns={{return_type="number"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(): number, string | nil, number | nil"}, {description=" Performs `$PATH` lookup of executable.\n     unix = require 'unix'\n     prog = assert(unix.commandv('ls'))\n     unix.execve(prog, {prog, '-hal', '.'}, {'PATH=/bin'})\n     unix.exit(127)\n If `prog` is an absolute path, then it's returned as-is. If `prog`\n contains slashes then it's not path searched either and will be\n returned if it exists. On Windows, it's recommended that you install\n programs from cosmos to c:/bin/ without any .exe or .com suffix, so\n they can be discovered like they would on UNIX. If you want to find\n a program like notepad on the $PATH using this function, then you\n need to specify \"notepad.exe\" so it includes the extension.", is_local=false, line=0, name="commandv", params={{name="prog", param_type="string"}}, returns={{return_type="string"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(prog: string): string, string | nil, number | nil"}, {description=" Exits current process, replacing it with a new instance of the\n specified program. `prog` needs to be an absolute path, see\n commandv(). `env` defaults to to the current `environ`. Here's\n a basic usage example:\n     unix.execve(\"/bin/ls\", {\"/bin/ls\", \"-hal\"}, {\"PATH=/bin\"})\n     unix.exit(127)\n `prog` needs to be the resolved pathname of your executable. You\n can use commandv() to search your `PATH`.\n `args` is a string list table. The first element in `args`\n should be `prog`. Values are coerced to strings. This parameter\n defaults to `{prog}`.\n `env` is a string list table. Values are coerced to strings. No\n ordering requirement is imposed. By convention, each string has its\n key and value divided by an equals sign without spaces. If this\n parameter is not specified, it'll default to the C/C++ `environ`\n variable which is inherited from the shell that launched redbean.\n It's the responsibility of the user to supply a sanitized environ\n when spawning untrusted processes.\n `execve()` is normally called after `fork()` returns `0`. If that isn't\n the case, then your redbean worker will be destroyed.\n This function never returns on success.\n `EAGAIN` is returned if you've enforced a max number of\n processes using `setrlimit(RLIMIT_NPROC)`.", is_local=false, line=0, name="execve", params={{name="prog", param_type="string"}, {name="args", param_type="{string}"}, {name="env", param_type="{string}"}}, returns={{return_type="nil"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(prog: string, args: {string}, env: {string}): nil, string | nil, number | nil"}, {description=" Executes program with PATH search.\n Unlike `execve()`, this function searches for `prog` in the\n directories listed in the `PATH` environment variable.\n If `argv` is not provided, it defaults to `{prog}`.\n This function never returns on success.", is_local=false, line=0, name="execvp", params={{name="prog", param_type="string"}, {name="argv", param_type="{string}"}}, returns={{return_type="nil"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(prog: string, argv?: {string}): nil, string | nil, number | nil"}, {description=" Executes program with PATH search and custom environment.\n Like `execvp()` but also allows specifying a custom environment.\n `envp` is a string list table where each string is typically\n in the form `\"KEY=value\"`. If not specified, inherits the\n current environment.\n This function never returns on success.", is_local=false, line=0, name="execvpe", params={{name="prog", param_type="string"}, {name="argv", param_type="{string}"}, {name="envp", param_type="{string}"}}, returns={{return_type="nil"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(prog: string, argv: {string}, envp?: {string}): nil, string | nil, number | nil"}, {description=" Executes program from file descriptor.\n This allows executing a program that has already been opened,\n which can be useful for executing programs that have been\n verified or for executing APE (Actually Portable Executable)\n binaries.\n `fd` is an open file descriptor pointing to an executable.\n `argv` is the argument vector passed to the program.\n `envp` is the environment. If not specified, inherits the\n current environment.\n This function never returns on success.", is_local=false, line=0, name="fexecve", params={{name="fd", param_type="number"}, {name="argv", param_type="{string}"}, {name="envp", param_type="{string}"}}, returns={{return_type="nil"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(fd: number, argv: {string}, envp?: {string}): nil, string | nil, number | nil"}, {description=" Spawns a new process.\n Unlike `fork()` + `execve()`, this uses `posix_spawn()` which\n can be more efficient on some platforms.\n `prog` must be an explicit path to the executable.\n `argv` is the argument vector passed to the program.\n `envp` is the environment. If not specified, inherits the\n current environment.\n Returns the child process id on success.", is_local=false, line=0, name="spawn", params={{name="prog", param_type="string"}, {name="argv", param_type="{string}"}, {name="envp", param_type="{string}"}}, returns={{return_type="number"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(prog: string, argv: {string}, envp?: {string}): number, string | nil, number | nil"}, {description=" Spawns a new process with PATH search.\n Like `spawn()` but searches for `prog` in the directories\n listed in the `PATH` environment variable.\n Returns the child process id on success.", is_local=false, line=0, name="spawnp", params={{name="prog", param_type="string"}, {name="argv", param_type="{string}"}, {name="envp", param_type="{string}"}}, returns={{return_type="number"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(prog: string, argv: {string}, envp?: {string}): number, string | nil, number | nil"}, {description=" Duplicates file descriptor.\n `newfd` may be specified to choose a specific number for the new\n file descriptor. If it's already open, then the preexisting one will\n be silently closed. `EINVAL` is returned if `newfd` equals `oldfd`.\n `flags` can have `O_CLOEXEC` which means the returned file\n descriptors will be automatically closed upon execve().\n `lowest` defaults to zero and defines the lowest numbered file\n descriptor that's acceptable to use. If `newfd` is specified then\n `lowest` is ignored. For example, if you wanted to duplicate\n standard input, then:\n     stdin2 = assert(unix.dup(0, nil, unix.O_CLOEXEC, 3))\n Will ensure that, in the rare event standard output or standard\n error are closed, you won't accidentally duplicate standard input to\n those numbers.", is_local=false, line=0, name="dup", params={{name="oldfd", param_type="number"}, {name="newfd", param_type="number"}, {name="flags", param_type="number"}, {name="lowest", param_type="number"}}, returns={{return_type="number"}, {return_type="string | nil"}, {return_type="number | nil"}}, signature="(oldfd: number, newfd?: number, flags?: number, lowest?: number): number, string | nil, number | nil"}, {description=" Creates fifo which enables communication between processes.\n - `O_CLOEXEC`: Automatically close file descriptor upon execve()\n - `O_NONBLOCK`: Request `EAGAIN` be raised rather than blocking\n - `O_DIRECT`: Enable packet mode w/ atomic reads and writes, so long\n   as they're no larger than `PIPE_BUF` (guaranteed to be 512+ bytes)\n   with support limited to Linux, Windows NT, FreeBSD, and NetBSD.\n Returns two file descriptors: one for reading and one for writing.\n Here's an example of how pipe(), fork(), dup(), etc. may be used\n to serve an HTTP response containing the output of a subprocess.\n     local unix = require \"unix\"\n     ls = assert(unix.commandv(\"ls\"))\n     reader, writer = assert(unix.pipe())\n     if assert(unix.fork()) == 0 then\n        unix.close(1)\n        unix.dup(writer)\n        unix.close(writer)\n        unix.close(reader)\n        unix.execve(ls, {ls, \"-Shal\"})\n        unix.exit(127)\n     else\n        unix.close(writer)\n        SetHeader('Content-Type', 'text/plain')\n        while true do\n           data, err, errno = unix.read(reader)\n           if data then\n              if data ~= \"\" then\n                 Write(data)\n              else\n                 break\n              end\n       